window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-07-28"]={"date": "2026-07-28", "dateKR": "2026년 7월 28일", "dateEN": "28 July 2026", "total": 92, "sections": [{"code": "TOP", "type": "news", "kTitle": "Section 1. 주요 뉴스", "eTitle": "Section 1. Top News", "items": [{"code": "TOP", "title": "Weekend lull fails to unlock Hormuz shipping", "src": "Splash247", "date": "2026-07-27", "kSum": "미국과 이란이 공격을 일시 중단하며 호르무즈 해협(Strait of Hormuz)은 약 2주 만에 가장 조용한 주말을 보냈으나 상업 선박 운항은 여전히 사실상 마비 상태다. 원유 탱커 통항은 하루 약 1척 수준에 그쳤고, 로이즈시장협회(LMA)는 통항료를 지불한 선박의 선체보험 담보를 중단하는 새 약관(LMA5708)을 내놨다. 미 중부사령부(CENTCOM)는 이란 항구 봉쇄를 뚫으려던 탱커를 무력화했다고 밝혔다.", "eSum": "The Strait of Hormuz had its quietest weekend in nearly two weeks after the US and Iran paused attacks, yet commercial shipping stayed close to paralysis with crude tanker transits at roughly one vessel per day. The Lloyd's Market Association issued new model wording (LMA5708) under which hull cover ceases once a vessel makes a Hormuz transit-fee payment. CENTCOM said it disabled a tanker that repeatedly tried to breach the US blockade of Iranian ports.", "kImp": "통항료·제재 리스크로 보험 담보가 끊기면서 선주의 호르무즈 기피가 구조화되고 있어, 중동발 원유·LNG 물류비와 선박 안전관리 부담이 장기화될 전망이다.", "eImp": "With insurance cover withdrawn over transit-fee and sanctions risk, owner avoidance of Hormuz is becoming structural, pointing to prolonged pressure on Middle East crude/LNG logistics costs and vessel risk management.", "url": "https://splash247.com/weekend-lull-fails-to-unlock-hormuz-shipping/"}, {"code": "TOP", "title": "Houthi threat brings Bab El-Mandeb crossings down another 50%", "src": "Seatrade Maritime News", "date": "2026-07-27", "kSum": "클락슨 리서치(Clarksons Research) 자료에 따르면 7월 25~26일 바브엘만데브(Bab El-Mandeb) 통항은 하루 평균 31척으로, 부진했던 2분기 대비 톤수 기준 50% 급감했다. 후티(Houthi)가 7월 20일 사우디 선박 봉쇄를 선언하고 얀부(Yanbu) 적재 탱커를 공격한 여파다. VLCC 통항은 하루 1척으로 줄었고 VLCC 수익은 주간 13% 상승한 하루 14만5,000달러를 기록했다.", "eSum": "Vessels transiting Bab El-Mandeb averaged 31 per day over 25-26 July, down 50% in tonnage terms on an already weak Q2, according to Clarksons Research. The drop followed the Houthi blockade of Saudi shipping declared on 20 July and an attack on a tanker that had loaded at Yanbu. VLCC crossings fell to about one per day, while VLCC earnings rose 13% on the week to $145,000/day.", "kImp": "홍해와 호르무즈의 이중 병목으로 탱커 운임 급등과 희망봉 우회 확대가 불가피해, 에너지 물류비 상승과 항로 재편 압력이 커지고 있다.", "eImp": "The twin Red Sea/Hormuz chokepoints are forcing tanker rates higher and pushing more Cape of Good Hope diversions, intensifying pressure on energy logistics costs and trade-route realignment.", "url": "https://www.seatrade-maritime.com/security/houthi-threat-brings-bab-el-mandeb-crossings-down-another-50-"}, {"code": "TOP", "title": "Merchant Vessel Sinks After Multiple Russian Cruise Missile Hits (Golden Leo)", "src": "The Maritime Executive", "date": "2026-07-26", "kSum": "7월 19일 러시아 순항미사일 3발에 피격됐던 기니비사우 선적·튀르키예 운영 화물선 골든 레오(Golden Leo)가 6일간 침수 끝에 오데사 앞바다에서 침몰했다. 옥수수를 싣고 출항 중 피격돼 인도 국적자 4명을 포함해 10명이 사망하고 8명이 구조됐다. 러시아의 우크라이나 곡물 수출 표적 공격으로 오데사 지역 상선 운항이 사실상 중단됐다.", "eSum": "The Guinea-Bissau-flagged, Turkish-operated cargo ship Golden Leo, hit by three Russian cruise missiles on 19 July, sank off Odesa after six days of progressive flooding. Outbound with corn when struck, the ship lost 10 people including four Indian nationals, with eight rescued. Russia's targeting of Ukraine's grain exports has effectively halted merchant traffic around Odesa.", "kImp": "흑해 곡물회랑에 대한 직접 공격으로 상선·선원 안전과 세계 곡물 공급망 리스크가 다시 부각되고 있다.", "eImp": "The direct strike on the Black Sea grain corridor renews concerns over merchant/crew safety and global grain supply-chain risk.", "url": "https://maritime-executive.com/article/merchant-vessel-sinks-after-multiple-russian-cruise-missile-hits"}, {"code": "TOP", "title": "Vietnamese Freighter Goes Down With 62 Crewmembers Aboard (Khoi Nguyen 18)", "src": "The Maritime Executive", "date": "2026-07-26", "kSum": "62명이 승선한 베트남 소형 화물선 코이응우옌 18(Khoi Nguyen 18)이 토요일 남중국해 파이어리크로스 암초(Fiery Cross Reef) 인근에서 악천후로 침몰했다. 조난 신호를 접수한 중국 구조선 6척과 베트남 선박, 헬기가 동원돼 대규모 수색이 벌어졌으며 17명이 실종됐다. 소형선 치고 이례적으로 많은 승선 인원이 주목됐다.", "eSum": "The small Vietnamese freighter Khoi Nguyen 18, carrying an unusually large complement of 62, sank in bad weather near Fiery Cross Reef in the South China Sea on Saturday. Six Chinese rescue vessels, a Vietnamese ship and a helicopter mounted a large-scale search after the distress call, with 17 crew reported missing.", "kImp": "분쟁 해역에서 발생한 대형 인명사고로 다국적 구조 협력과 소형선 안전·정원 관리 문제가 부각됐다.", "eImp": "A major loss of life in disputed waters highlights multinational rescue cooperation and safety/manning concerns for small vessels.", "url": "https://maritime-executive.com/article/vietnamese-freighter-goes-down-with-62-crewmembers-aboard"}, {"code": "TOP", "title": "Japanese bank merger creates $12.8bn ship finance heavyweight", "src": "Splash247", "date": "2026-07-27", "kSum": "일본 마쓰야마 소재 이요긴 홀딩스(Iyogin Holdings)와 에히메은행(Ehime Bank)이 경영통합 기본합의서에 서명해, 선박·해운 대출 2조1,000억 엔(약 128억 달러) 규모의 은행 그룹이 탄생한다. 이요은행은 전체 여신의 약 4분의 1이 해운 대출로 일본 3위·세계 10위 선박금융 기관이다. 통합은 주주·규제 승인을 거쳐 내년 4월 1일 발효될 예정이다.", "eSum": "Matsuyama-based Iyogin Holdings and Ehime Bank signed a basic agreement to integrate, forming a group with more than 2.1trn yen ($12.8bn) in ship and maritime loans. Iyo Bank, where maritime lending is roughly a quarter of its book, ranks as Japan's third-largest ship finance lender and 10th globally. The deal is scheduled to take effect on 1 April next year, subject to approvals.", "kImp": "이마바리(Imabari) 해운 클러스터를 배후로 한 지방은행 통합으로 선박금융 공급 여력이 커져, 일본 선주·조선소의 자금조달 환경에 영향을 줄 전망이다.", "eImp": "Consolidation of regional lenders anchored in the Imabari maritime cluster enlarges ship-finance capacity, shaping funding conditions for Japanese owners and yards.", "url": "https://splash247.com/japanese-bank-merger-creates-12-8bn-ship-finance-heavyweight/"}, {"code": "TOP", "title": "Diana Renews Push for Genco While Permitting Tender Offer to Expire", "src": "The Maritime Executive", "date": "2026-07-27", "kSum": "다이애나 시핑(Diana Shipping)이 젠코 시핑앤트레이딩(Genco Shipping & Trading) 인수를 위한 공개매수를 만료시키면서도 합병 제안은 유지하며 압박을 이어갔다. 다이애나는 공개매수가 협상의 걸림돌이라는 젠코 측 주장을 제거하기 위한 조치라고 밝혔고, 젠코 이사회는 희석 우려와 저평가 매각 논란을 들어 제안을 거부하고 있다. 다이애나는 여전히 젠코 최대주주다.", "eSum": "Diana Shipping kept up pressure in its bid for Genco Shipping & Trading, letting its tender offer expire while keeping its merger proposal on the table. Diana said ending the tender removed a 'mechanism' Genco cited as a barrier to talks; Genco's board continues to reject the offer, citing potential dilution and below-market vessel sales. Diana remains Genco's largest shareholder.", "kImp": "드라이벌크 자산가치 고점 논쟁 속에서 벌어진 대형 M&A 공방으로, 벌크 선사 통합의 향방을 가늠하는 사안이다.", "eImp": "A high-stakes drybulk M&A battle amid debate over peak asset values, serving as a bellwether for bulk-sector consolidation.", "url": "https://maritime-executive.com/article/diana-renews-push-for-genco-while-permitting-tender-offer-to-expire"}, {"code": "TOP", "title": "DH Shipbuilding sets annual order record with fresh suezmax pair", "src": "Splash247", "date": "2026-07-27", "kSum": "한국 대한조선(DH Shipbuilding)이 유럽 신규 선주로부터 15만7,000dwt 수에즈막스 원유운반선 2척(2,713억 원, 약 1억9,600만 달러)을 추가 수주하며 올해 누계 17척으로 연간 최다 수주 기록을 세웠다. 올해 수주액은 약 2조2,500억 원으로 연간 목표의 1.6배에 달하며, 수주잔량은 36척으로 2029년 말까지 건조 일정이 채워졌다.", "eSum": "South Korea's DH Shipbuilding booked two more 157,000 dwt suezmax crude tankers from a new European customer for KRW271.3bn ($196m), lifting its 2026 intake to a record 17 ships. Year-to-date orders reach about KRW2.25trn, roughly 1.6 times its annual target, with the orderbook at 36 vessels filling the Haenam yard through end-2029.", "kImp": "수에즈막스 집중 전략이 성과를 내며 한국 중형 조선소의 탱커 수주 호황과 도크 만재 상황을 보여주는 사례다.", "eImp": "A focused suezmax strategy pays off, illustrating the tanker-order boom and full order books at mid-size Korean yards.", "url": "https://splash247.com/dh-shipbuilding-sets-annual-order-record-with-fresh-suezmax-pair/"}, {"code": "TOP", "title": "Reshaping the industry - progress on US maritime legislation", "src": "Seatrade Maritime News", "date": "2026-07-28", "kSum": "미국의 해양행동계획(Maritime Action Plan, MAP) 관련 입법이 하원 국방수권법(NDAA) 수정안에 담겨 통과되며 수십 년 만의 대대적 해사법 개편이 진행 중이다. 'SHIPS for America' 법 재작성, 백악관 해양안보보좌관 신설, 200억 달러 규모 해양안보신탁기금(Maritime Security Trust Fund) 신설, 수입 컨테이너·로로 화물에 대한 미국 국적선 우선적재 의무 등이 포함됐다. 상원은 9월 노동절 이후 심의에 나선다.", "eSum": "US maritime legislation tied to the Maritime Action Plan (MAP) advanced as amendments embedded in the House-passed NDAA, marking the most significant overhaul of federal maritime law in decades. Provisions include a rewritten SHIPS for America Act, a new White House Maritime Security Advisor, a $20bn Maritime Security Trust Fund, and a mandatory US-flag preference for inbound container and ro-ro cargo. The Senate takes it up after Labor Day in September.", "kImp": "화물 우선적재·조선금융·인력양성을 아우르는 미국 자국선 우대 정책으로, 상업 무역 영역까지 처음 진입하는 국적선 의무는 글로벌 정기선·자동차선 무역에 파급될 수 있다.", "eImp": "A US-flag preference regime spanning cargo preference, shipbuilding finance and workforce - reaching private commercial trade for the first time - could ripple across global liner and car-carrier trades.", "url": "https://www.seatrade-maritime.com/regulations/reshaping-the-industry-progress-on-us-maritime-legislation"}]}, {"code": "ACC", "type": "accident", "kTitle": "Section 2. 해양사고", "eTitle": "Section 2. Accidents", "items": [{"code": "ACC", "title": "베트남 화물선 'Khoi Nguyen 18(코이응우옌 18)' 남중국해 침몰… 62명 중 17명 실종", "src": "gCaptain", "date": "2026-07-25", "kSum": "베트남 선적 소형 화물선 Khoi Nguyen 18(코이응우옌 18, 70m·1,911 dwt, IMO 9846354)이 2026년 7월 25일 저녁 남중국해 스프래틀리 제도 융수초(Yongshu Reef, 中 관할) 인근에서 폭풍우 속 통제 불능 침수로 침몰. 승선 62명 중 45명 구조, 17명 실종. 중국 SAR선 Nanhai Jiu 115(난하이주 115)가 조난 신호탄을 확인하고 중국·베트남 선박이 수색·구조 진행.", "eSum": "The Vietnamese-flagged general cargo ship Khoi Nguyen 18 (70 m, 1,911 dwt, IMO 9846354) sank on the evening of 25 July 2026 in the South China Sea near Yongshu (Fiery Cross) Reef in the Spratlys after uncontrolled water ingress in stormy weather. Of 62 aboard, 45 were rescued and 17 remained missing; the Chinese SAR vessel Nanhai Jiu 115 spotted a distress flare and Chinese and Vietnamese ships carried out the search.", "kCause": "정확한 원인은 미공개. 직접 원인은 악천후 항해 중 통제 불능 침수이며, 선체 손상·화물 이동·복원성 상실 또는 침몰 직전 기관 고장·전원 상실(블랙아웃) 가능성이 제기됨(추정).", "eCause": "Cause not yet disclosed. The direct trigger was uncontrolled flooding while sailing in a storm; hull damage, cargo shift/loss of stability, or a machinery failure/blackout prior to sinking are suspected (presumed).", "kLes": "소형·노후 화물선은 악천후 시 복원성·수밀 관리와 출항(Go/No-Go) 판단이 특히 중요하며, 조기 조난 경보와 구명뗏목·구명동의 즉시 착용 태세가 생존율을 좌우함(추정).", "eLes": "For small, older cargo ships, weather-routing and go/no-go decisions and watertight/stability management are critical in heavy weather; early distress alerting and immediate access to liferafts and lifejackets are decisive for survival (presumed).", "url": "https://gcaptain.com/17-missing-after-vietnamese-vessel-sinks-in-south-china-sea/"}, {"code": "ACC", "title": "곡물선 'Golden Leo(골든 레오)', 피격 1주일 만에 오데사 앞바다서 침몰", "src": "gCaptain", "date": "2026-07-26", "kSum": "기니비사우 선적 곡물 화물선 Golden Leo(골든 레오)가 2026년 7월 26일(일) 우크라이나 오데사(Odesa) 인근 흑해에서 침몰. 옥수수를 싣고 7월 19일 초르노모르스크(Chornomorsk)를 출항한 직후 러시아 순항미사일 공격으로 선체·상부구조가 심각히 손상돼 승조원 9명 사망·8명 대피했고, 감항성을 상실한 뒤 결국 침몰.", "eSum": "The Guinea-Bissau-flagged grain carrier Golden Leo sank in the Black Sea near Odesa on Sunday 26 July 2026, a week after a 19 July Russian missile strike. Carrying corn out of Chornomorsk, the ship suffered severe hull and superstructure damage that killed nine crew (eight evacuated) and left her unseaworthy, leading to the sinking.", "kCause": "근본 원인은 러시아 미사일 공격으로 인한 선체·상부구조 손상과 감항성 상실. 피격 후 구난·예인 지연도 최종 침몰에 영향을 준 것으로 추정.", "eCause": "Root cause was structural damage and loss of seaworthiness from the Russian missile strike; delay in salvage/towage after the hit likely contributed to the eventual sinking (presumed).", "kLes": "전시 해상회랑 운항 위험이 지속되므로 항로·시간대 회피와 손상통제·긴급 예인 체계 구축이 필요하며, 피격 선박을 조기에 안전 항구로 예인하면 후속 침몰·오염을 줄일 수 있음(추정).", "eLes": "With wartime corridor risks persisting, route/timing avoidance and robust damage-control and emergency-tow arrangements are essential; early towing of a struck vessel to a safe haven can prevent later sinking and pollution (presumed).", "url": "https://gcaptain.com/vessel-sinks-a-week-after-being-struck-by-russian-fire/"}, {"code": "ACC", "title": "벌크선 'Gozne(괴즈네)', 흑해 튀르키예 연안서 기관 고장으로 표류… 예인 구조", "src": "Shipwreck Log", "date": "2026-07-27", "kSum": "130m·12,034 dwt 벌크선 Gozne(괴즈네, IMO 9146132)이 2026년 7월 27일 오전 튀르키예 튀르켈리 등대(Türkeli Lighthouse) 인근 흑해에서 기관 고장으로 추진력을 상실하고 표류. 위네(Ünye)에서 카라비가(Karabiga)로 항해 중 발생했으며, 튀르키예 해안경비청(KEGM) 예인선 Kurtarma 3(쿠르타르마 3)가 예인해 튀르켈리 정박지로 안전 이동. 인명 피해·선체 손상·오염 없음.", "eSum": "The 130 m, 12,034 dwt bulk carrier Gozne (IMO 9146132) lost propulsion and drifted off Türkeli Lighthouse in the Black Sea on the morning of 27 July 2026 while en route from Ünye to Karabiga. The Turkish coast authority (KEGM) tug Kurtarma 3 towed her safely to Türkeli anchorage. No injuries, damage or pollution reported.", "kCause": "원인은 기관 고장(추진기관 정지)으로 명시됨. 세부 결함은 미공개이며 연료·윤활 계통 또는 보조기기 고장 가능성이 있음(추정).", "eCause": "Stated cause was a machinery breakdown (loss of propulsion); the specific defect was undisclosed, possibly a fuel/lube-oil system or auxiliary-machinery failure (presumed).", "kLes": "협수로·연안 통항 중 추진력 상실에 대비한 비상 대응 절차와 조기 예인 요청, 정기 기관 정비·상태감시가 좌초·충돌 위험을 예방함(추정).", "eLes": "Prepare for propulsion loss in coastal/confined waters with contingency procedures and early tug requests; planned machinery maintenance and condition monitoring help avert grounding or collision (presumed).", "url": "https://shipwrecklog.com/log/2026/07/gozne/"}, {"code": "ACC", "title": "베트남 어선 'QNg 90729 TS', 남중국해서 방향타 이탈로 조종불능… 예인 구조", "src": "Shipwreck Log", "date": "2026-07-25", "kSum": "22m 베트남 어선 QNg 90729 TS가 2026년 7월 25일 오후 남중국해 다남(Da Nam)섬 인근에서 강풍·높은 파도·폭우를 피해 입항하려던 중 방향타(타)가 이탈해 조종불능 상태에 빠짐. 베트남 당국 순시선이 예인해 안전 입항했고, 승선 어민 38명 전원 무사(사상자·오염 없음).", "eSum": "The 22 m Vietnamese fishing vessel QNg 90729 TS lost steering when its rudder detached while trying to enter port for shelter near Da Nam Island in the South China Sea on the afternoon of 25 July 2026 amid strong winds, high seas and heavy rain. A Vietnamese patrol vessel towed her safely into port; all 38 aboard were unharmed with no pollution.", "kCause": "직접 원인은 악천후 항해 중 방향타 이탈. 타 부착부(핀틀·거전 등) 피로·정비 불량 또는 과도한 조타 하중 가능성(추정).", "eCause": "Direct cause was rudder detachment while navigating in heavy weather; fatigue or poor maintenance of the rudder fittings (pintles/gudgeons) or excessive steering loads are possible (presumed).", "kLes": "소형 어선의 조타장치·타 연결부 정기 점검과 악천후 조기 피항 판단, 승선 정원 및 구명설비 관리가 다수 인명 위험을 줄임(추정).", "eLes": "Regular inspection of steering gear and rudder fittings on small fishing vessels, timely decisions to seek shelter, and management of crew numbers and lifesaving gear reduce mass-casualty risk (presumed).", "url": "https://shipwrecklog.com/log/2026/07/qng-90729-ts/"}]}, {"code": "PSC", "type": "news", "kTitle": "Section 3. 항만국통제", "eTitle": "Section 3. Port State Control", "items": [{"code": "PSC", "title": "파리 MoU(Paris MoU) 2025년 PSC 연차보고서 발표 – 억류율 4.18%로 상승, 화재안전 결함 최다", "src": "Maritime Cyprus (파리 MoU 2025 연차보고서 재보도)", "date": "2026-07-26", "kSum": "파리 MoU(Paris MoU, 파리 양해각서)가 2025년 항만국통제(PSC, Port State Control) 연차보고서를 발표했다. 2025년 회원국은 총 16,474건을 점검했고, 이 중 9,879척(약 60%)에서 결함이 확인됐으며 688척이 억류됐다. 지역 억류율은 4.18%로 2024년 4.03%, 2023년 3.86%에서 3년 연속 상승했다. 입항금지(ban)도 19척으로 늘어 최근 수년간의 낮은 수준을 벗어났다. 화재안전(fire safety) 결함이 여전히 최다 항목이며, ISM(국제안전관리규약) 이행 미흡과 선박·장비 정비 불량이 핵심 억류 사유로 지목됐다.", "eSum": "The Paris MoU released its 2025 Port State Control Annual Report. Member authorities carried out 16,474 inspections in 2025, recording deficiencies on 9,879 ships (about 60%) and detaining 688 vessels. The regional detention rate rose to 4.18%, up from 4.03% in 2024 and 3.86% in 2023 - a third consecutive annual increase. Bans also climbed to 19 ships, ending several years of low numbers. Fire safety remained the leading deficiency area, while shortcomings in ISM implementation and maintenance of ship and equipment were the key detention drivers.", "kImp": "억류율이 3년 연속 오르고 입항금지가 급증한 것은 PSC 압박이 구조적으로 강화되고 있음을 뜻한다. 화재안전·ISM·정비 결함이 반복되는 만큼, 선사·기국(flag State)·선급(RO)은 실질적 안전관리체제(SMS) 이행과 화재안전 설비 상시 점검으로 억류 리스크를 선제적으로 관리해야 한다.", "eImp": "A third consecutive rise in the detention rate and a jump in bans signal structurally tightening PSC pressure. With fire safety, ISM and maintenance deficiencies recurring, operators, flag States and ROs should proactively manage detention risk through effective SMS implementation and continuous fire-safety readiness.", "url": "https://maritimecyprus.com/2026/07/26/paris-mou-releases-annual-report-on-port-state-control-for-2025-detention-rates-rising/"}]}, {"code": "PCTC", "type": "news", "kTitle": "Section 4. 자동차운반선", "eTitle": "Section 4. PCTC / Car Carriers", "items": [{"code": "PCTC", "title": "Vehicle backlog squeezes capacity at Hambantota port", "src": "Splash247", "date": "2026-07-27", "kSum": "스리랑카 함반토타 국제항(Hambantota International Port)이 ro-ro 물동량 급증으로 야드 용량 압박을 받자 장기 보관 차량의 조속한 반출을 수입업체에 촉구하고 있다. 현재 수입·환적 차량 5만 대 이상을 보관 중이며, 약 1,278대는 3개월 넘게(이 중 581대는 1년 이상) 장치돼 있다. 항만은 수입차 10일·환적차 21일의 무료 보관 이후 체화료를 부과하며, 지연 사유의 상당수를 서류·금융 등 항만 통제 밖 행정 문제로 돌렸다. 2025년 72만6,153대를 처리한 데 이어 연간 약 100만 대 처리 능력을 목표로 야드를 확장 중이다.", "eSum": "Hambantota International Port in Sri Lanka is pressing importers to clear long-stored vehicles as surging ro-ro volumes strain terminal yard capacity. The port holds over 50,000 import and transhipment vehicles, with about 1,278 units parked for more than three months (581 of them for over a year). It grants 10 days free storage for imports and 21 for transhipment before demurrage, and blames many delays on documentation, banking and other administrative issues outside its control. After handling 726,153 vehicles in 2025, it is expanding toward roughly 1m units of annual ro-ro capacity.", "kImp": "완성차 해상물류 급증이 선박뿐 아니라 항만 터미널 야드 용량까지 병목으로 확산되고 있음을 보여주는 사례로, PCTC 기항지의 혼잡·체선 리스크와 신흥 환적 허브 간 처리능력 확충 경쟁을 시사한다.", "eImp": "Shows the finished-vehicle boom is now bottlenecking terminal yard capacity, not just ships, signalling congestion and demurrage risk at PCTC call ports and a capacity race among emerging transhipment hubs.", "url": "https://splash247.com/vehicle-backlog-squeezes-capacity-at-hambantota-port/"}]}, {"code": "WW", "type": "news", "kTitle": "Section 5. 발레니우스 빌헬름센", "eTitle": "Section 5. Wallenius Wilhelmsen", "items": [{"code": "WW", "title": "EUKOR Completes First Green Methanol Bunkering for New Shaper-Class Car Carrier in Shanghai", "src": "gCaptain", "date": "2026-07-21", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)의 합작사 유코카캐리어스(EUKOR)가 상하이항에서 셰이퍼급(Shaper Class) 1번선 아틱 턴(Arctic Tern)에 약 2,800톤의 그린 메탄올을 공급하며 첫 메탄올 벙커링을 완료했다. SIPG 에너지가 전용 벙커링선을 이용해 하역과 동시에(SIMOPS) 작업을 수행했으며, 상하이 도시 생활폐기물로 생산된 ISCC-EU 인증 연료가 쓰였다. 국제 PCTC 운항사가 상하이에서 현지 생산 그린 메탄올을 공급받은 첫 사례다.", "eSum": "EUKOR Car Carriers, jointly owned by Wallenius Wilhelmsen and Hyundai Motor Group, completed its first green methanol bunkering, delivering about 2,800 tonnes to Arctic Tern, the first Shaper Class PCTC, at the Port of Shanghai. SIPG Energy carried out the ship-to-ship operation simultaneously with cargo work (SIMOPS), using ISCC-EU certified fuel produced from Shanghai municipal solid waste. It was the first time an international PCTC operator received locally produced green methanol in Shanghai.", "kImp": "메탄올 이중연료 자동차운반선의 상업 운항이 본격화되는 가운데 대규모 그린 메탄올 벙커링 인프라가 실증됨으로써, 발레니우스 빌헬름센의 2027년 넷제로 엔드투엔드 서비스 목표 달성을 위한 중요한 이정표가 된다.", "eImp": "As methanol dual-fuel car carriers move into commercial service, demonstrating large-scale green methanol bunkering infrastructure marks an important milestone toward Wallenius Wilhelmsen's ambition to offer net-zero end-to-end services by 2027.", "url": "https://gcaptain.com/eukor-completes-first-green-methanol-bunkering-for-new-shaper-class-car-carrier-in-shanghai/"}]}, {"code": "EE", "type": "news", "kTitle": "Section 6. 에너지 효율·탈탄소", "eTitle": "Section 6. Energy Efficiency", "items": [{"code": "EE", "title": "EPA Refers California's Harbor Air Pollution Rules to Congress for Review", "src": "The Maritime Executive", "date": "2026-07-27", "kSum": "미국 트럼프 행정부가 캘리포니아 대기자원위원회(CARB)의 항만 관련 청정대기법 규정 두 건을 의회검토법(CRA)에 따라 의회에 회부했다. 대상은 정박 중 육상전원(cold-ironing) 사용을 의무화하고 컨테이너선 절반에 육상전력 사용과 선대 배출 70% 감축을 요구하는 '정박 중 원양선박(CARB at Berth)' 규정과, 항만 예인선의 미세먼지 배출을 EPA Tier IV보다 엄격히 제한하는 '상업용 항만선박(Commercial Harbor Craft)' 규정이다.", "eSum": "The Trump administration referred two California Air Resources Board (CARB) harbor Clean Air Act rules to Congress under the Congressional Review Act: the 'Ocean-Going Vessels at Berth' shore-power (cold-ironing) rule requiring half of boxships to use shore power and fleets to cut emissions 70%, and the 'Commercial Harbor Craft' rule limiting particulate matter from harbor tugs beyond EPA Tier IV. The move could roll back California's stricter vessel emissions standards.", "kImp": "미국 최대 항만권역인 캘리포니아의 선박·예인선 배출규제 완화 가능성은 육상전력·탈탄소 투자와 선사 컴플라이언스 전략에 직접 영향을 미친다. 규제 불확실성 확대는 항만 배출저감 로드맵의 후퇴 위험을 시사한다.", "eImp": "A potential rollback of vessel and harbor-craft emission rules in California, the largest US port region, directly affects shore-power and decarbonisation investment and carrier compliance strategy, signalling regulatory uncertainty and a possible retreat on port emission-reduction roadmaps.", "url": "https://maritime-executive.com/article/epa-refers-california-s-harbor-air-pollution-rules-to-congress-for-review"}, {"code": "EE", "title": "IBIA calls for further investigation into marine fuel quality concerns", "src": "Container News", "date": "2026-07-27", "kSum": "국제벙커산업협회(IBIA)가 셰일오일 성분이 의심되는 잔사유(residual) 선박연료와 최근 선박 운항 문제를 연결짓는 보고에 대해 추가 기술조사를 촉구했다. 기술작업반 검토 결과 직접적 인과관계는 확인되지 않았으며, 셰일오일 유래 탄화수소는 ISO 8217상 허용 원료로 그 존재만으로 품질결함·부적합의 증거가 아니라고 밝혔다. 연료 블렌드 다양화에 따라 투명성·추적성·품질보증 강화가 필요하다고 강조했으며, 싱가포르 해사항만청(MPA)은 관련 벙커링 메모 3호(2026)를 발행했다.", "eSum": "The International Bunker Industry Association (IBIA) called for further technical investigation into reports linking ship operational problems to residual marine fuels containing compounds that may indicate shale oil. Its Technical Working Group found no direct causal link, noting shale-oil-derived hydrocarbons are a permitted ISO 8217 feedstock and their presence alone is not evidence of non-compliance. IBIA urged greater transparency, traceability and quality assurance as fuel blends diversify; Singapore's MPA issued Bunkering Memo No. 3 of 2026.", "kImp": "대체연료·블렌드 확대로 연료 품질·적합성 리스크가 커지는 가운데, ISO 8217 기준과 공급망 추적성 강화 논의는 선박 운항 안정성과 연료 컴플라이언스에 직결된다.", "eImp": "As alternative fuels and blends expand, fuel-quality and fitness risks grow; the debate over ISO 8217 standards and supply-chain traceability bears directly on vessel operational reliability and fuel compliance.", "url": "https://container-news.com/ibia-calls-for-further-investigation-into-marine-fuel-quality-concerns/"}]}, {"code": "DIG", "type": "news", "kTitle": "Section 7. 디지털라이제이션", "eTitle": "Section 7. Digitalization", "items": [{"code": "DIG", "title": "HD KSOE agrees ABS deal for software-defined vessel platform", "src": "Smart Maritime Network", "date": "2026-07-27", "kSum": "HD한국조선해양(HD KSOE)이 ABS 컨설팅(ABS Consulting)과 소프트웨어 정의 선박(software-defined vessel) 플랫폼 개발을 지원하는 협약을 체결했다. 선박 시스템을 소프트웨어 중심으로 통합·제어하는 차세대 선박 아키텍처 개발을 목표로 한다.", "eSum": "HD Korea Shipbuilding & Offshore Engineering (HD KSOE) signed an agreement with ABS Consulting to support development of a software-defined vessel platform, targeting a next-generation ship architecture in which onboard systems are integrated and controlled through software.", "kImp": "소프트웨어 정의 선박은 기능 업데이트·자율운항·데이터 통합의 기반으로, 세계 최대 조선그룹과 선급 진영의 협력은 디지털 선박 표준화 경쟁에서 중요한 이정표다.", "eImp": "Software-defined vessels underpin over-the-air updates, autonomy and data integration; cooperation between the world's largest shipbuilding group and a class society is a key milestone in the race to standardise digital ships.", "url": "https://smartmaritimenetwork.com/2026/07/27/hd-ksoe-agrees-abs-deal-for-software-defined-vessel-platform/"}, {"code": "DIG", "title": "ArcelorMittal to standardise digital operations across global dry bulk terminals", "src": "Smart Maritime Network", "date": "2026-07-27", "kSum": "아르셀로미탈(ArcelorMittal)이 로이드선급(Lloyd's Register, LR)과 협력해 전 세계 벌크 터미널 네트워크를 위한 글로벌 운영 표준 모델을 개발한다. 터미널 운영을 디지털화·표준화해 효율과 데이터 일관성을 높이는 것이 목표다.", "eSum": "ArcelorMittal is working with Lloyd's Register (LR) to develop a global operating model for its dry bulk terminal network, aimed at digitalising and standardising terminal operations to improve efficiency and data consistency.", "kImp": "대형 화주가 주도하는 터미널 운영 디지털 표준화는 항만·물류 통합 데이터화 흐름을 보여주며, 공급망 가시성과 운영 효율 개선의 사례가 된다.", "eImp": "Cargo-owner-led standardisation of terminal operations illustrates the wider digitalisation of port and logistics data, offering a template for improved supply-chain visibility and operational efficiency.", "url": "https://smartmaritimenetwork.com/2026/07/27/arcelormittal-to-standardise-digital-operations-across-global-dry-bulk-terminals/"}, {"code": "DIG", "title": "Maritime among highest adopters of AI for supplier risk management - report", "src": "Smart Maritime Network", "date": "2026-07-27", "kSum": "한 보고서에 따르면 해상운송(해운) 기업은 조달·공급업체 리스크·지속가능성 관리에 인공지능(AI)을 가장 적극적으로 도입하는 산업군에 속하는 것으로 나타났다. 해운업계가 AI 기반 조달·리스크 분석 채택에서 앞서가고 있음을 시사한다.", "eSum": "Marine transport companies are among the most active adopters of AI for procurement, supplier-risk and sustainability management, according to a new report, indicating the shipping sector is ahead in adopting AI-driven procurement and risk analytics.", "kImp": "조달·공급망 리스크 관리에서 AI 도입 확대는 해운의 디지털 성숙도를 보여주며, 제재·컴플라이언스·ESG 대응 역량 강화로 이어진다.", "eImp": "Growing AI adoption in procurement and supply-chain risk management reflects shipping's digital maturity and strengthens capabilities in sanctions, compliance and ESG management.", "url": "https://smartmaritimenetwork.com/2026/07/27/maritime-among-highest-adopters-of-ai-for-supplier-risk-management-report/"}, {"code": "DIG", "title": "Saronic and Samsung Heavy partner for US autonomous-focused shipyard", "src": "Smart Maritime Network", "date": "2026-07-27", "kSum": "미국 자율운항 선박 기업 사로닉(Saronic)이 삼성중공업(Samsung Heavy Industries, SHI)과 자율운항 가능 선박 개발을 위한 전략적 파트너십을 체결했다. 이는 사로닉이 텍사스 브라운스빌에 추진 중인 33억 달러 규모 '포트 알파(Port Alpha)' 조선소 계획과 연계된다.", "eSum": "US autonomous-vessel firm Saronic signed a strategic partnership with Samsung Heavy Industries (SHI) to jointly develop autonomy-capable vessels, tied to Saronic's planned $3.3 billion 'Port Alpha' shipyard in Brownsville, Texas.", "kImp": "미국 자율운항 기술과 한국 조선 역량의 결합은 자율·무인 선박의 상용 건조 확대와 미국 조선업 재건 흐름을 보여주는 주목할 협력이다.", "eImp": "Combining US autonomy technology with Korean shipbuilding expertise marks a notable move toward commercial-scale construction of autonomous and unmanned vessels and the revival of US shipbuilding.", "url": "https://smartmaritimenetwork.com/2026/07/27/saronic-and-samsung-heavy-partner-for-us-autonomous-focused-shipyard/"}, {"code": "DIG", "title": "Pindustry becomes majority shareholder in VSTEP", "src": "Smart Maritime Network", "date": "2026-07-27", "kSum": "해양 시뮬레이션 기업 VSTEP이 네덜란드 산업투자사 핀더스트리(Pindustry)를 신규 최대주주로 맞이했다. 기존 판 덴 베르흐(Van den Berg) 소유 지분을 대체하는 것으로, 선박 조종·훈련 시뮬레이터 사업 확장을 위한 지배구조 변화다.", "eSum": "Maritime simulation company VSTEP has welcomed Dutch industrial investor Pindustry as its new majority shareholder, replacing the Van den Berg family ownership, in a change aimed at expanding its ship-handling and training simulator business.", "kImp": "선박 조종·훈련 시뮬레이션은 안전훈련과 자율운항 검증의 핵심 디지털 기술로, 투자 유치는 해사 교육·시뮬레이션 시장의 성장세를 반영한다.", "eImp": "Ship-handling and training simulation is a core digital technology for safety training and autonomy validation; the new investment reflects growth in the maritime training and simulation market.", "url": "https://smartmaritimenetwork.com/2026/07/27/pindustry-becomes-majority-shareholder-in-vstep/"}]}, {"code": "TECH", "type": "news", "kTitle": "Section 8. 선박관리 기술", "eTitle": "Section 8. Ship Manager Technical", "items": [{"code": "TECH", "title": "Explora Journeys, LNG 추진 크루즈선 'Explora III' 인도 (핀칸티에리 건조)", "src": "Container News", "date": "2026-07-26", "kSum": "MSC 그룹의 럭셔리 브랜드 Explora Journeys가 핀칸티에리(Fincantieri) 제노바 세스트리 포넨테 조선소에서 LNG 추진 크루즈선 Explora III를 인도받았다. 총 6척·35억 유로 규모 선단 확장 프로그램 중 3번째 선박이다. 선박은 바이오-LNG·합성 LNG·바이오연료 등 재생연료로도 운항 가능하며, 육상전원(shore power) 연결로 접안 중 엔진을 정지해 배출을 줄일 수 있다. RINA로부터 Green Plus(환경성능)·소음진동(Comfort Noise and Vibration)·수중방사소음 저감(Dolphin)·Polar Code C 등 인증을 취득했다. 후속선 Explora V·VI에는 연료전지가 탑재될 예정이다.", "eSum": "Explora Journeys took delivery of the LNG-powered Explora III at Fincantieri's Sestri Ponente yard in Genoa - the third of a six-ship, €3.5bn fleet-expansion programme. The ship can also run on renewable fuels (bio-LNG, synthetic LNG and biofuels), features shore-power connectivity that lets it switch off its engines while alongside, and holds RINA notations including Green Plus, Comfort Noise and Vibration, Dolphin (reduced underwater radiated noise) and Polar Code C. Later sisters Explora V and VI will additionally be fitted with fuel cells.", "kImp": "LNG 이중연료 기관, 육상전원, 재생연료 대응 등 최신 추진·기관 사양을 담은 크루즈 신조선 인도로, 기술관리팀에 대체연료 기관·연료 시스템의 실선 적용 사례를 제공한다. 후속선의 연료전지 탑재 계획은 크루즈 부문의 무탄소 추진 전환 방향과 향후 정비·기술관리 요구사항 변화를 시사한다.", "eImp": "A newbuild carrying the latest propulsion and machinery specs - LNG dual-fuel engines, shore power and renewable-fuel readiness - gives technical teams a reference point for alternative-fuel machinery and fuel systems in service. The planned addition of fuel cells on later ships points to the cruise sector's zero-carbon propulsion path and the evolving maintenance and technical-management demands that will follow.", "url": "https://container-news.com/explora-journeys-takes-delivery-of-lng-powered-explora-iii/"}]}, {"code": "HR", "type": "news", "kTitle": "Section 9. 해기인력·선원", "eTitle": "Section 9. Marine HR", "items": [{"code": "HR", "title": "걸프 분쟁 속 발 묶인 선원 지원 (Supporting Stranded Seafarers Amid the Gulf Conflict)", "src": "The Mission to Seafarers", "date": "2026-07-27", "kSum": "중동 분쟁으로 호르무즈 해협(Strait of Hormuz) 통항이 사실상 막히면서 미션투시퍼러스(The Mission to Seafarers)가 발이 묶인 선원들에게 긴급 복지 지원을 제공하고 있다. IMO 자료를 인용해 2만여 명의 선원이 영향을 받고 약 3,000척이 지연됐으며 상륙허가와 선원 교대가 중단됐다고 밝혔다. UAE·바레인·아카바(요르단)·키프로스 현장팀이 대면 및 왓츠앱·전화·Happy@Sea 앱으로 지원한다.", "eSum": "As the Middle East conflict effectively closes the Strait of Hormuz, The Mission to Seafarers is delivering emergency welfare support to stranded crews. Citing IMO figures, it says over 20,000 seafarers are affected and around 3,000 vessels delayed, with shore leave and crew changes suspended. Teams in the UAE, Bahrain, Aqaba (Jordan) and Cyprus provide in-person and remote help via WhatsApp, phone and the Happy@Sea app.", "kImp": "지정학적 분쟁이 세계 무역을 떠받치는 선원 인력을 직접 위협하며, 복지·송환 공백을 자선단체가 메우는 현실을 드러낸다.", "eImp": "It shows how geopolitical conflict directly endangers the human workforce behind global trade and exposes the welfare and repatriation gap charities are scrambling to fill.", "url": "https://www.missiontoseafarers.org/news/supporting-stranded-seafarers-amid-the-gulf-conflict"}, {"code": "HR", "title": "잉글랜드 북동부 선원센터, 바다로부터의 안식처 (A Sanctuary from the Sea in the North East)", "src": "The Mission to Seafarers", "date": "2026-07-27", "kSum": "노스티스·하틀풀(North Tees and Hartlepool) 선원센터가 16년째 운영자 에이든 웹스터(Aidan Webster)의 관리 아래 월 약 300시간 개방하며 예배실·도서실·휴게공간을 제공한다. 짧은 정박 시간 탓에 시내 왕복이 어려운 선원들에게 휴식과 교류, 도움 요청의 공간이 된다. 웹스터는 일부 선원이 스스로 목숨을 끊었을 만큼 항해가 주는 정신건강 부담을 강조했다.", "eSum": "The Seafarers' Centre for North Tees and Hartlepool, run for 16 years by manager Aidan Webster, is open about 300 hours a month with a chapel, library and social space. Short port turnarounds that prevent a trip into town make the centre a place to rest, socialise and seek help. Webster stresses the mental-health toll of seafaring, noting some workers have taken their own lives.", "kImp": "육상 선원센터가 선원 정신건강을 지키고 현대 해운 일정의 고립감을 완화하는 핵심 역할을 함을 보여준다.", "eImp": "It underlines the role of shore-based seafarers' centres in protecting crew mental health and countering the isolation of modern shipping schedules.", "url": "https://www.missiontoseafarers.org/news/a-sanctuary-from-the-sea-in-the-north-east"}, {"code": "HR", "title": "뉴펀들랜드 세인트존스, 복지지원의 새 시대 (A New Era of Welfare Support in St John's, Newfoundland)", "src": "The Mission to Seafarers", "date": "2026-07-27", "kSum": "캐나다 뉴펀들랜드 세인트존스(St John's, Newfoundland)에 항만노조 공간을 함께 쓰는 새 선원센터가 문을 열었고 해운 관계자 약 40명이 참석했다. 물리적 방문이 어려운 원격지 선원까지 지원하도록 설계돼 이미 키티맷(BC)·처칠(매니토바) 항만 활동을 검토 중이며 최근 위기 선박을 원격 지원했다. 정식 개관은 9월 예정이며 메모리얼대학의 선원 웰빙 연구와 연계된다.", "eSum": "A new Seafarers' Centre has opened in St John's, Newfoundland, in space shared with the longshoremen's union, with about 40 maritime stakeholders attending. Built to reach beyond its walls, it already eyes work at Kitimat (BC) and Churchill (Manitoba) and recently helped a vessel in crisis remotely. A formal opening is planned for September, with ties to Memorial University research on seafarer wellbeing.", "kImp": "복지 사각지대인 원격 항만까지 지원을 확장하고, 직접 방문이 어려운 선원에게 다가가는 네트워크형 모델을 제시한다.", "eImp": "It expands welfare coverage into remote, hard-to-reach ports and models a networked approach to reaching crews that centres cannot physically visit.", "url": "https://www.missiontoseafarers.org/news/a-new-era-of-welfare-support-in-st-johns-newfoundland"}, {"code": "HR", "title": "거리와 다양성을 넘는 항만 채플린 양성 (Building Chaplaincy Across Distance and Diversity)", "src": "The Mission to Seafarers", "date": "2026-07-27", "kSum": "중남미·카리브 지역에서 미션투시퍼러스는 파나마·트리니다드토바고·코스타리카·브라질·아르헨티나에 걸쳐 단 7명의 항만 채플린에 의존하며, 잦은 항만 행정 교체와 원격지, 선원 착취 위험에 직면해 있다. 지역 책임자 이언 허친슨 세르반테스(Fr Ian Hutchinson Cervantes) 신부는 휴스턴 NAMMA 콘퍼런스를 통한 신규 채플린 양성과 독일선원선교회와의 파나마 공동활동을 소개하며 '돌봄의 연속성'을 강조했다. 칠레 발파라이소·킨테로, 아르헨티나 로사리오 등 태평양 연안으로의 확대를 검토 중이다.", "eSum": "Across Central and South America and the Caribbean the Mission relies on just seven port chaplains (Panama, Trinidad and Tobago, Costa Rica, Brazil, Argentina) amid shifting port administrations, remote ports and crew-exploitation risks. Regional Director Fr Ian Hutchinson Cervantes describes training new chaplains via the NAMMA conference in Houston and joint work in Panama with German Seaman's Mission partners, stressing 'continuity of care'. Expansion down the Pacific coast, including Valparaiso and Quintero (Chile) and Rosario (Argentina), is being explored.", "kImp": "주요 해운 권역의 복지 인력이 얼마나 얇은지, 그리고 지속가능한 돌봄 체계를 구축하려는 노력을 부각한다.", "eImp": "It highlights how thin welfare coverage is across a major shipping region and the effort to build sustainable, vocation-driven care for crews.", "url": "https://www.missiontoseafarers.org/news/building-chaplaincy-across-distance-and-diversity"}, {"code": "HR", "title": "변화하는 해운 산업에서 여성 선원 지원 (Supporting Women in a Changing Maritime Industry)", "src": "The Mission to Seafarers", "date": "2026-07-27", "kSum": "전 세계 선원 중 여성은 약 1%에 불과하지만 브라질 13%, 머스크(Maersk)·CMA CGM의 채용 확대 등으로 늘고 있으며, 미션투시퍼러스는 'Inclusion at Sea' 프로그램으로 여성 선원 복지를 확대하고 있다. 여성의 40%가 위생용품 폐기함을 이용하지 못하고 3명 중 1명이 성희롱을 경험했으나 복지 인력의 6%만이 대응 훈련을 받았다는 격차를 지적했다. 주요 크루즈 항만에 여성 복지관을 채용하고 시설을 점검하며 성희롱·정신건강·트라우마 관련 무료 교육을 제공한다.", "eSum": "Women are about 1% of the global seafaring workforce but rising (13% in Brazil; Maersk and CMA CGM drives), and the Mission is scaling welfare for female crew via its Inclusion at Sea programme. It cites stark gaps: 40% of women report no access to sanitary bins, one in three has faced sexual harassment, and only 6% of welfare staff are trained to respond. The Mission is recruiting female welfare officers in key cruise ports, reviewing facilities and offering free training on harassment, mental health and trauma.", "kImp": "여성 채용을 늘리는 흐름 속에서 복지 인프라와 인력 훈련이 뒤처져 유지·안전 리스크가 커지고 있음을 경고한다.", "eImp": "As the industry recruits more women, it flags that welfare infrastructure and staff training lag dangerously behind, creating retention and safeguarding risks.", "url": "https://www.missiontoseafarers.org/news/supporting-women-in-a-changing-maritime-industry"}, {"code": "HR", "title": "피터 사무총장 7월 블로그: 바다의 성평등 (Peter's July 2026 Blog)", "src": "The Mission to Seafarers", "date": "2026-07-27", "kSum": "사무총장 피터 라우치(Peter Rouch)는 한 젊은 여성 항해사가 도선사로부터 '엄마가 될 예순 번의 월간 기회를 놓쳤다'는 말을 들은 일화로 바다의 성평등을 가로막는 뿌리 깊은 문화 장벽을 짚었다. 여성은 여전히 선원의 2% 미만이며 대부분 크루즈에 몰려 있고, 정책과 목표만으로는 굳은 통념을 바꿀 수 없다고 주장한다('culture eats strategy for breakfast'). 그는 남성 위주 업계가 통념에 의문을 제기하고 멘토링하며 기회를 진정으로 열어두는 협력자가 되어야 한다고 촉구했다.", "eSum": "Secretary General Peter Rouch reflects on cultural barriers to gender diversity at sea, opening with a young female officer told by a pilot she had 'missed sixty monthly opportunities' to become a mother. He argues women remain under 2% of seafarers, mostly in cruise, and that policies and targets alone will not shift deep assumptions ('culture eats strategy for breakfast'). He calls on the largely male industry to act as allies by questioning assumptions, mentoring and keeping opportunities genuinely open.", "kImp": "선원 다양성을 채용 목표가 아니라 문화 변화와 인재 유지의 문제로 규정한다.", "eImp": "It frames seafarer diversity as a culture-change and talent-retention issue, not just a recruitment-target one.", "url": "https://www.missiontoseafarers.org/news/peters-july-2026-blog"}, {"code": "HR", "title": "크루웰페어위크 2026: 심리적 안전이 미래형 선원의 핵심 (Crew Welfare Week 2026: Psychological safety is vital for a future-ready crew)", "src": "SAFETY4SEA", "date": "2026-07-28", "kSum": "2026 크루웰페어위크(Crew Welfare Week) 패널 토론에서 전문가들은 인적 역량이 안전한 선박 운항과 효과적 리더십, 선원 유지의 근간이라고 강조했다. 특히 선원이 실수나 우려를 자유롭게 말할 수 있는 '심리적 안전(psychological safety)'이 미래에 대비한 선원을 만드는 핵심 요소로 지목됐다. 인적 기술과 소통 문화를 조직적으로 육성해야 한다는 점이 부각됐다.", "eSum": "At a 2026 Crew Welfare Week panel, experts stressed that human skills are fundamental to safe vessel operations, effective leadership and crew retention. 'Psychological safety'—crews feeling free to speak up about mistakes or concerns—was highlighted as vital to building a future-ready crew. The discussion urged systematic cultivation of human skills and open communication.", "kImp": "인적 역량과 심리적 안전을 선원 유지와 안전 성과를 좌우하는 전략 요소로 다룬다.", "eImp": "It treats human skills and psychological safety as strategic levers for crew retention and safety performance.", "url": "https://safety4sea.com/cm-crew-welfare-week-2026-psychological-safety-is-vital-for-a-future-ready-crew/"}]}, {"code": "HSEQ", "type": "news", "kTitle": "Section 10. HSEQ·손해방지", "eTitle": "Section 10. HSEQ", "items": [{"code": "HSEQ", "title": "교훈: 구를 수 있는 물건은 항상 고위험으로 다뤄라 (Lessons learned: Stuff that can roll should always be treated as high-risk for rolling)", "src": "SAFETY4SEA / IMCA", "date": "2026-07-28", "kSum": "IMCA는 리그 인근 해상 화물작업 중 갑판에 실린 파이프 한 개가 선체 동요와 너울로 미끄러져 굴러간 사고에서 교훈을 도출했다. 핵심 교훈은 최초 적재 방식과 무관하게 구를 수 있는 모든 물체는 기본적으로 고위험으로 간주해 확실히 고박·초크 처리해야 한다는 것이다.", "eSum": "SAFETY4SEA relays an IMCA Safety Flash case in which, during offshore cargo operations alongside a rig, a single pipe stowed on deck shifted and rolled due to vessel motion and swell. The core lesson: any object capable of rolling must by default be treated as high-risk and be properly secured and chocked, regardless of how it was stowed.", "kImp": "선체 동요를 고려한 갑판 화물 고박과 동적 위험성 평가가 화물 이동·낙하물 부상을 막는 핵심임을 재확인한다.", "eImp": "It reinforces that deck-cargo securing and dynamic risk assessment for vessel motion are essential to prevent shifting-load and dropped-object injuries.", "url": "https://safety4sea.com/lessons-learned-stuff-that-can-roll-should-always-be-treated-as-high-risk-for-rolling/"}, {"code": "HSEQ", "title": "밀폐구역 사망 방지 위해 공학적 안전장치 촉구 (MarinePALS calls for engineering safeguards to prevent enclosed space deaths)", "src": "SAFETY4SEA / MarinePALS", "date": "2026-07-28", "kSum": "마린팔스(MarinePALS)는 개정된 IMO 권고가 밀폐구역 출입 절차를 강화했지만 훈련과 관리적 통제만으로는 부족하다고 지적했다. 애초에 위험한 출입 자체를 물리적으로 막는 공학적 안전장치가 필요하다며, 반복되는 밀폐구역 사망을 근본적으로 줄여야 한다고 촉구했다.", "eSum": "MarinePALS argues that although revised IMO recommendations strengthen enclosed-space entry procedures, enhanced training and administrative controls alone are not enough. It calls for engineering safeguards that physically prevent unsafe entry in the first place, to address the persistent toll of enclosed-space fatalities.", "kImp": "절차·훈련 의존에서 벗어나 위험을 원천 제거하는 상위 단계의 공학적 통제로의 전환을 시사한다.", "eImp": "It signals a shift from reliance on procedures and training toward higher-order engineering controls to eliminate one of shipping's most lethal recurring hazards.", "url": "https://safety4sea.com/marinepals-calls-for-engineering-safeguards-to-prevent-enclosed-space-deaths/"}, {"code": "HSEQ", "title": "세계 간염의 날: 선원 건강의 장벽 허물기 (World Hepatitis Day: Breaking down barriers to seafarer health)", "src": "SAFETY4SEA", "date": "2026-07-28", "kSum": "세계 간염의 날(World Hepatitis Day, 7월 28일)을 맞아, 간경변·간암으로 진행될 수 있는 바이러스성 간염을 충분히 다뤄지지 않는 선원 건강 위험으로 조명했다. 인식 제고, 검사, 백신 접종, 낙인 해소 등 장벽을 허무는 데 초점을 맞췄다.", "eSum": "Marking World Hepatitis Day (28 July), the article highlights viral hepatitis—which can lead to serious liver disease, cirrhosis and cancer—as an under-addressed seafarer health risk. It focuses on breaking down barriers such as awareness, testing, vaccination and stigma to protect crew health.", "kImp": "선원 예방의학과 직업건강은 선원 복지와 승무 적합성에 직결되는 핵심 HSEQ 이슈다.", "eImp": "Occupational health and preventive care for seafarers are core HSEQ concerns affecting crew welfare and fitness for duty.", "url": "https://safety4sea.com/cm-world-hepatitis-day-breaking-down-barriers-to-seafarer-health/"}, {"code": "HSEQ", "title": "ISWAN의 HEART 프레임워크: 선원 스트레스 관리의 실용법 (ISWAN's HEART framework: Practical ways for seafarers to manage stress)", "src": "SAFETY4SEA / ISWAN", "date": "2026-07-27", "kSum": "2026 크루웰페어위크에서 ISWAN의 수치타 굽타(Suchita Gupta)는 선원이 정신·신체 건강을 지키도록 돕는 간단한 실용 도구로 'HEART' 프레임워크를 소개했다. 업무 부담, 고립, 피로 등 누적되는 스트레스 요인에 대응하는 방법을 제시한다.", "eSum": "At 2026 Crew Welfare Week, ISWAN's Suchita Gupta introduced the 'HEART' framework as a simple, practical tool to help seafarers protect their mental and physical wellbeing. It offers coping strategies for the compounding stressors of life at sea, including workload, isolation and fatigue.", "kImp": "선원 정신건강은 스트레스·피로가 인적 오류로 이어지는 안전 요인이므로, 실용적 웰빙 도구가 복지와 운항 안전을 함께 뒷받침한다.", "eImp": "Seafarer mental health is a recognised safety factor, so practical wellbeing tools support both crew welfare and operational safety.", "url": "https://safety4sea.com/cm-iswans-heart-framework-practical-ways-for-seafarers-to-manage-stress/"}]}, {"code": "KR", "type": "news", "kTitle": "Section 11. 한국 해운시장", "eTitle": "Section 11. Korean Shipping Market", "items": [{"code": "KR", "title": "팬스타그룹, 북극항로 시범운항 화주설명회 성황…8월 22일 부산 출항", "src": "쉬핑뉴스넷", "date": "2026-07-27", "kSum": "팬스타그룹이 7월 24일 서울 코엑스에서 한국해양진흥공사·한국무역협회와 공동으로 북극항로(NSR) 시범운항 화주설명회를 열어 150여 명이 참석했다고 27일 밝혔다. 8월 22일 부산항을 출발해 로테르담·함부르크·그단스크로 향하는 국내 최초 북극항로 시범운항에 2,800TEU급 컨테이너선을 투입하며, 전용 예약시스템 오픈 이후 자동차부품·합성수지 등 실제 부킹이 이어지고 있다.", "eSum": "Pan Star Group said on the 27th that its July 24 shipper briefing in Seoul on a Northern Sea Route (NSR) trial voyage, held with KOBC and KITA, drew over 150 attendees. Korea's first NSR trial departs Busan on Aug 22 for Rotterdam, Hamburg and Gdansk with a 2,800 TEU boxship, and real bookings for auto parts and resins are already coming in.", "kImp": "국적선사 최초의 북극항로 상업 시범운항으로, 한국 해운의 신항로 개척과 부산항의 유럽 연계 물류 거점화 가능성을 보여준다.", "eImp": "As the first commercial NSR trial by a Korean carrier, it signals Korea's push into new routes and Busan's potential as a Europe-linked logistics hub.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=71334"}, {"code": "KR", "title": "삼성중공업, 환헤지 부담 해소 임박…연내 최대 2척 FDC 수주 가능성", "src": "쉬핑뉴스넷", "date": "2026-07-27", "kSum": "메리츠증권은 27일 삼성중공업 2분기 영업이익이 3,250억원(YoY +58.7%)을 기록했으나 100% 환헤지 정책과 일회성 비용으로 컨센서스를 하회했다고 분석했다. 고환율 시기 수주분이 반영되는 2026년말~2027년초부터 수익성이 개선되며, 2분기 실적설명회에서 연내 최대 2척의 부유식데이터센터(FDC) 수주 가능성이 재확인됐다.", "eSum": "Meritz Securities said on the 27th that Samsung Heavy's Q2 operating profit of 325bn won (+58.7% YoY) missed consensus due to its 100% FX-hedge policy and one-off costs. Margins should improve from late 2026 as higher-won-era orders are recognized, and the firm reaffirmed it could win up to two floating data centers (FDC) this year.", "kImp": "조선 빅3의 실적 구조와 신성장 동력(FDC·FLNG)을 보여주며, 환율과 수주 시점이 국내 조선 수익성에 미치는 영향을 시사한다.", "eImp": "Highlights the earnings structure and new growth drivers (FDC/FLNG) of Korea's big-3 shipbuilders and how FX and order timing drive margins.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=71319"}, {"code": "KR", "title": "HMM 美 서안 WUT 터미널, HD현대삼호에 크레인 4기 발주…처리능력 88만TEU로 확대", "src": "쉬핑뉴스넷", "date": "2026-07-26", "kSum": "HMM이 운영하는 미국 워싱턴주 타코마항 WUT 터미널이 HD현대삼호와 크레인 4기 공급계약을 체결했다고 26일 밝혔다. 노후 안벽크레인 2기 교체와 야드크레인 2기 추가로 연간 하역능력을 59만TEU에서 88만TEU로 확대하며, HD현대삼호가 설계·제작·설치·시운전을 2028년까지 턴키로 수행한다.", "eSum": "HMM said on the 26th that its WUT terminal at Tacoma, Washington signed a deal with HD Hyundai Samho for four cranes. Replacing two aged quay cranes and adding two yard cranes will lift annual handling capacity from 590k to 880k TEU, delivered turnkey by HD Hyundai Samho by 2028.", "kImp": "HMM의 해외 터미널 인프라 투자와 국내 조선사(HD현대삼호) 크레인 수주가 맞물린 사례로, 선대·항만 동반 경쟁력 강화 전략을 보여준다.", "eImp": "Shows HMM expanding overseas terminal infrastructure while sourcing cranes from a Korean builder, underscoring a joint fleet-and-port competitiveness strategy.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=71308"}, {"code": "KR", "title": "해수부, 상반기 민간 항만개발사업 2,523억원 유치…전년比 17.5%↑", "src": "코리아쉬핑가제트", "date": "2026-07-27", "kSum": "해양수산부는 2026년 상반기 전국 지방해양수산청·지자체가 비관리청 항만개발사업 78건을 허가했으며 민간투자 총사업비가 2,523억원으로 전년 동기(2,147억원)보다 17.5% 늘었다고 27일 밝혔다. 태양광 등 저탄소시설이 21건으로 가장 많았고, 목포지방해양수산청이 1,107억원으로 투자규모가 가장 컸다.", "eSum": "The Ministry of Oceans and Fisheries said on the 27th it approved 78 private (non-managing-authority) port-development projects in H1 2026, with total private investment of 252.3bn won, up 17.5% YoY. Low-carbon facilities such as solar led with 21 cases, and the Mokpo office drew the largest 110.7bn won.", "kImp": "항만 분야 민간투자가 친환경·고부가 물류시설 중심으로 확대되는 흐름을 보여주는 해수부 정책 지표다.", "eImp": "A ministry policy indicator showing private port investment expanding toward eco-friendly, high-value logistics facilities.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147707"}, {"code": "KR", "title": "팬스타, SIPG와 부산-상하이 카페리 항로 개척 협의…APEC서 AI 물류 발표", "src": "코리아쉬핑가제트", "date": "2026-07-27", "kSum": "팬스타그룹 김현겸 회장이 24~25일 중국을 방문해 세계 1위 항만 운영사 상하이국제항무그룹(SIPG)과 부산-상하이 주 2항차 크루즈 페리 신규 노선 개발을 협의했다고 밝혔다. 노선이 개설되면 부산과 중국을 잇는 유일한 여객선 항로가 되며, 김 회장은 APEC 부대행사에서 한국 해운물류기업의 AI 전환 사례도 발표했다.", "eSum": "Pan Star Chairman Kim Hyun-kyum visited China on the 24-25th to discuss a new twice-weekly Busan-Shanghai cruise ferry with SIPG, the world's top container-port operator. The route would be the only passenger link between Busan and China; Kim also presented Korean shipping-logistics AI transformation at an APEC side event.", "kImp": "부산항의 대중국 여객·크루즈 연계 강화와 국적선사의 AI 물류 역량을 보여주는 사례다.", "eImp": "Demonstrates strengthening of Busan's China passenger/cruise links and a Korean carrier's AI logistics capabilities.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147703"}, {"code": "KR", "title": "북미항로 HMM·코스코, 8월 운임인상 시동…부산발 동안운임 20주 연속 상승", "src": "코리아쉬핑가제트", "date": "2026-07-27", "kSum": "7월 북미항로는 중국발 밀어내기 수요 둔화와 공급 확대로 상승세가 꺾였으나 여전히 높은 수준을 유지했다. HMM은 8월 1일·15일 아시아-미주 화물에 TEU당 2,700달러 GRI(운임인상)를 실시하며, 부산발 북미 동안 운임은 20주 연속 올라 7월 평균 FEU당 8,546달러로 전월비 42% 상승했다.", "eSum": "In July the North America trade cooled on softer China front-loading and added capacity but stayed high. HMM will apply Aug 1 and 15 GRIs of $2,700/TEU on Asia-US cargo; Busan-US East Coast rates rose for a 20th straight week, averaging $8,546/FEU in July, up 42% MoM.", "kImp": "국적선사 HMM의 운임 회복 전략과 북미항로 시황을 보여주는 지표로, 하반기 컨테이너 수익성을 가늠하게 한다.", "eImp": "A gauge of HMM's rate-recovery strategy and North America market conditions, signaling container profitability for H2.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147680"}, {"code": "KR", "title": "HD현대마린솔루션, 2분기 영업이익 976억원…전년比 17.6%↑", "src": "한국해운신문", "date": "2026-07-28", "kSum": "HD현대마린솔루션이 2026년 2분기 매출 5,804억원(YoY +24.1%), 영업이익 976억원(YoY +17.6%)을 기록했다고 밝혔다. 선박 부품·서비스(AM), 친환경 개조, 디지털 솔루션 등 3대 핵심사업과 벙커링 매출 증가가 실적을 견인했으며, 친환경 솔루션 매출은 전년 대비 38.1% 늘었다.", "eSum": "HD Hyundai Marine Solution posted Q2 2026 revenue of 580.4bn won (+24.1% YoY) and operating profit of 97.6bn won (+17.6% YoY). Growth in its three core businesses—aftermarket parts/services, eco-friendly retrofits and digital solutions—plus bunkering drove results, with eco-solution sales up 38.1%.", "kImp": "신조 호황에 따른 선박 애프터마켓·친환경 개조 수요 확대가 국내 기자재·서비스 기업 실적으로 이어지는 흐름을 보여준다.", "eImp": "Shows how the newbuild boom is feeding aftermarket and eco-retrofit demand into Korean equipment/service firms' earnings.", "url": "http://www.maritimepress.co.kr/news/articleView.html?idxno=332352"}, {"code": "KR", "title": "中 조선, 상반기 신조 수주 1억2,106만DWT '역대 최고'…세계 점유율 82.3%", "src": "한국해운신문", "date": "2026-07-27", "kSum": "중국 산업정보부에 따르면 올해 1~6월 중국 조선 신조 수주량이 1억2,106만DWT로 전년 대비 173.1% 급증하며 전세계 선박 발주량의 82.3%를 차지한 것으로 나타났다. 올해 상반기 전세계 발주량은 전년비 12.3% 증가했으며, 중국은 1분기 5,953만DWT, 2분기 6,153만DWT를 수주했다.", "eSum": "Chinese shipyards won a record 121.06m DWT of new orders in H1, up 173.1% YoY and 82.3% of global orders, per China's industry ministry. Global orders rose 12.3% YoY in H1, with China winning 59.53m DWT in Q1 and 61.53m DWT in Q2.", "kImp": "중국 조선의 압도적 수주 점유율은 한국 조선 빅3의 경쟁 환경과 고부가 선종 집중 전략의 배경을 보여준다.", "eImp": "China's overwhelming order share frames the competitive backdrop for Korea's big-3 builders and their focus on high-value vessel types.", "url": "http://www.maritimepress.co.kr/news/articleView.html?idxno=332331"}, {"code": "KR", "title": "\"울산항 경제 파급효과 연간 33조원\"…UPA 부가가치 창출 전략 용역", "src": "한국해운신문", "date": "2026-07-27", "kSum": "울산항만공사(UPA)는 27일 '울산항 부가가치 창출 극대화를 위한 항만산업 지원전략' 연구용역 최종보고회에서 울산항의 지역 생산유발효과가 연 33.4조원, 부가가치 유발 11.2조원, 취업유발 10.7만 명에 이른다고 밝혔다. 2025년 물동량 1억9,260만t을 처리했으며 수소·암모니아 친환경 에너지 거점으로 체질 개선을 추진한다.", "eSum": "Ulsan Port Authority (UPA) said on the 27th that Ulsan Port generates 33.4tn won in annual regional production effect, 11.2tn won in value-added and 107,000 jobs, per a final research report. It handled 192.6m tons in 2025 and is shifting toward a hydrogen/ammonia green-energy hub.", "kImp": "국내 최대 산업지원 항만의 경제적 가치를 정량화하고 친환경 에너지 항만으로의 전환 방향을 제시한 사례다.", "eImp": "Quantifies the economic value of Korea's largest industrial-support port and charts its shift toward a green-energy hub.", "url": "http://www.maritimepress.co.kr/news/articleView.html?idxno=332340"}]}, {"code": "INS", "type": "news", "kTitle": "Section 12. 해상보험 (H&M)", "eTitle": "Section 12. Marine Insurance (H&M)", "items": [{"code": "INS", "title": "Vessels switch Asia voyages to via Suez amid Houthi warnings", "src": "Insurance Marine News", "date": "2026-07-27", "kSum": "후티(Houthi)가 특정 항만에 기항한 선박을 공격하겠다고 위협하면서, 다수 선박이 바브엘만데브(Bab al-Mandab) 해협을 피해 수에즈(Suez) 운하 경유 등으로 아시아 항로를 재조정하고 있다. 홍해(Red Sea)·아덴만 위험 재고조로 전쟁위험(war risk) 담보 수요와 항로별 추가보험료가 다시 부각되고 있다.", "eSum": "Following Houthi threats to attack ships that had called at certain ports, a number of vessels are rerouting Asia voyages away from the Bab al-Mandab strait, reviving demand for war-risk cover and route-specific additional premiums.", "kImp": "홍해 위험 재부상은 선체·전쟁위험 언더라이터(underwriter)의 추가보험료(AP) 산정과 항로 배제조항에 직접 영향을 미쳐, 선주의 항로 선택과 보험비용 구조를 좌우한다.", "eImp": "A renewed Red Sea threat directly feeds hull and war-risk underwriters' additional-premium pricing and routing exclusions, shaping owners' voyage choices and insurance costs.", "url": "https://insurancemarinenews.com/insurance-marine-news/vessels-switch-asia-voyages-to-via-suez-amid-houthi-warnings/"}, {"code": "INS", "title": "Declared Hormuz tanker crossings nearing an effective zero", "src": "Insurance Marine News", "date": "2026-07-27", "kSum": "호르무즈(Hormuz) 해협을 통과한 것으로 신고된 탱커 수가 7월 23일 목요일 단 1척으로, 5월 7일 이후 최저치로 떨어졌다. 7월 22일에는 3척이 통과했다고 분석업체가 밝혔다. 긴장 고조로 사실상 통항이 멈추면서 전쟁위험 담보 시장이 위축되고 있다.", "eSum": "The number of tankers declaring a Strait of Hormuz crossing fell to just one on Thursday 23 July, the lowest since 7 May, with three on 22 July, as escalation pushes declared transits toward zero.", "kImp": "호르무즈 통항 급감은 전쟁위험 보험료 급등과 담보 가용성 축소를 방증하며, 세계 원유 물동량 및 선체·화물 보험 익스포저 전반에 파급된다.", "eImp": "Collapsing Hormuz transits signal soaring war-risk premiums and shrinking capacity, with knock-on effects for oil flows and hull/cargo insurance exposure.", "url": "https://insurancemarinenews.com/insurance-marine-news/declared-hormuz-tanker-crossings-nearing-an-effective-zero/"}, {"code": "INS", "title": "Two tankers leaking oil near Larak Island in Strait of Hormuz", "src": "Insurance Marine News", "date": "2026-07-27", "kSum": "윈드워드(Windward AI)가 호르무즈 해협 북단에서 두 선박의 기름 유출을 보고했다. 피격됐던 파나막스급 석유제품선 카보말레아스(Kavomaleas, IMO 1042823)를 포함해 라라크(Larak) 섬 인근에서 오염이 확인되며 선체·오염 손해 규모가 커지고 있다.", "eSum": "Windward AI reported leaks from two vessels at the northern end of the Strait of Hormuz, including the previously struck panamax products tanker Kavomaleas, adding to hull and pollution losses near Larak Island.", "kImp": "피격에 따른 선체 전손·오염 손해는 전쟁위험·H&M 보험금 청구로 직결되며, 유출 대응·잔해 처리 비용까지 손해액을 확대시킨다.", "eImp": "Strike-related hull losses and pollution translate directly into war-risk and H&M claims, with spill response and salvage costs inflating the loss quantum.", "url": "https://insurancemarinenews.com/insurance-marine-news/two-tankers-leaking-oil-near-larak-island-in-strait-of-hormuz/"}, {"code": "INS", "title": "Saudi products tanker reported struck in Red Sea", "src": "Insurance Marine News", "date": "2026-07-27", "kSum": "2014년 건조·사우디 선적 화학·석유제품선 NCC 마사(NCC Masa, IMO 9688336, 29,785gt)가 7월 25일 토요일 이른 시각 홍해에서 피격된 것으로 보고됐다. 사우디 내셔널(National) 계열 선박에 대한 공격으로 홍해 전쟁위험 익스포저가 재확인됐다.", "eSum": "The 2014-built, Saudi-flagged chemical/products tanker NCC Masa was reported struck in the Red Sea early on Saturday 25 July, underscoring continued war-risk exposure in the corridor.", "kImp": "홍해에서의 추가 피격은 전쟁위험 언더라이터의 항로별 추가보험료 인상과 담보 조건 강화로 이어져, 통항 선박의 보험비용을 재차 끌어올린다.", "eImp": "A fresh Red Sea strike pressures war-risk underwriters toward higher route APs and tighter terms, again raising insurance costs for transiting ships.", "url": "https://insurancemarinenews.com/insurance-marine-news/saudi-products-tanker-reported-struck-in-red-sea/"}, {"code": "INS", "title": "Leaking tanker sees Oman demand action from owner", "src": "Insurance Marine News", "date": "2026-07-27", "kSum": "오만 교통통신정보기술부가 카롤린 베젠기(Caroline Bezengi, IMO 9224439) 선주에게 24시간 내 조치를 요구하는 긴급 지시를 발령했다. 유출 대응·오염 방지 책임을 선주에게 물리며 오염배상책임 리스크가 부각됐다.", "eSum": "Oman's transport ministry issued an urgent 24-hour directive to the owner of the Caroline Bezengi over the leaking tanker, placing pollution-response liability squarely on the owner.", "kImp": "연안국의 신속 조치 명령은 오염배상책임·잔해제거 비용을 선주와 보험자에게 전가하며, 대응 지연 시 손해와 규제 리스크가 급증한다.", "eImp": "A coastal-state directive shifts pollution and wreck-response costs onto owner and insurer, with delay sharply escalating loss and regulatory risk.", "url": "https://insurancemarinenews.com/insurance-marine-news/leaking-tanker-sees-oman-demand-action-from-owner/"}, {"code": "INS", "title": "Marine round-up : 27th July 2026", "src": "Insurance Marine News", "date": "2026-07-27", "kSum": "가이아나 국영 바리마(Barima, IMO 5036896) 침몰 사망자가 7월 23일 추가 시신 수습으로 72명으로 늘어나는 등 선체·화물·책임 관련 손해 소식을 모은 마린 라운드업. 여러 사고·손해 동향이 마린 보험 청구 흐름을 요약한다.", "eSum": "The daily marine round-up collates hull, cargo and liability loss items, including the death toll from the sinking of Guyana's state-owned Barima rising to 72 on 23 July.", "kImp": "다발성 손해 사건을 한눈에 정리해 마린 보험자의 클레임 동향·리스크 축적을 파악하는 데 유용하다.", "eImp": "A consolidated view of multiple loss events helps marine insurers track claims trends and risk accumulation.", "url": "https://insurancemarinenews.com/insurance-marine-news/marine-round-up-27th-july-2026/"}]}, {"code": "PNI", "type": "news", "kTitle": "Section 13. P&I 클럽", "eTitle": "Section 13. P&I Clubs", "items": [{"code": "PNI", "title": "North Standard reports continued expansion in its Directors Report for Policy Year 2025-2026", "src": "Insurance Marine News", "date": "2026-07-27", "kSum": "국제그룹(International Group) 소속 P&I 클럽이자 마린 보험사인 노스스탠더드(NorthStandard)가 2026년 2월 20일 종료된 정책연도(policy year) 동안 특종보험(specialty) 사업이 지속 확대되며 '지속가능한' 성장을 달성했다고 이사회 보고서에서 밝혔다.", "eSum": "International Group club and marine insurer NorthStandard said in its Directors' Report that, during the policy year to 20 February 2026, its specialty business continued to expand, achieving sustainable growth.", "kImp": "국제그룹 대형 클럽의 실적·확장 기조는 2026/27 갱신 조건, 풀(Pool) 재보험 부담, 회원 보험료 방향을 가늠하는 지표로, 선주의 P&I 비용 전망에 직접적이다.", "eImp": "A major IG club's results and expansion signal the direction of 2026/27 renewal terms, pooling costs and members' premiums, bearing directly on owners' P&I cost outlook.", "url": "https://insurancemarinenews.com/insurance-marine-news/north-standard-reports-continued-expansion-in-its-directors-report-for-policy-year-2025-2026/"}]}, {"code": "CLASS", "type": "news", "kTitle": "Section 15. 선급", "eTitle": "Section 15. Classification Societies", "items": [{"code": "CLASS", "title": "콘래드조선소·삼성중공업(SHI), ABS로부터 12,000㎥ LNG 벙커링 ATB 설계 AiP 획득", "src": "Manifold Times", "date": "2026-07-28", "kSum": "미국 콘래드조선소(Conrad Shipyard)와 삼성중공업(SHI)이 미국선급(ABS)으로부터 12,000㎥급 LNG 벙커링 압항부선(articulated tug and barge, ATB) 설계에 대한 기본승인(AiP)을 공동 취득했다. 이 선박은 미국 내 건조를 목표로 하며, 한미조선협력센터(KUSPC) 개소식(7월 23일)에서 발표됐다.", "eSum": "US-based Conrad Shipyard and Samsung Heavy Industries (SHI) jointly received an Approval in Principle (AiP) from the American Bureau of Shipping (ABS) for the design of a 12,000-cbm LNG bunkering articulated tug and barge (ATB) intended for US construction, announced at the Korea-U.S. Shipbuilding Partnership Center (KUSPC) opening on 23 July.", "kImp": "ABS의 AiP는 한미 조선협력 및 미국 내 LNG 벙커링 인프라 확충을 뒷받침하는 기술적 검증으로, 대체연료 벙커링 선박 분야에서 선급의 역할을 부각시킨다.", "eImp": "The ABS AiP provides technical validation supporting Korea-US shipbuilding cooperation and the build-out of US LNG bunkering infrastructure, highlighting the class society's role in alternative-fuel bunkering vessels.", "url": "https://www.manifoldtimes.com/news/conrad-shipyard-and-shi-secure-abs-aip-for-lng-bunkering-vessel-design/"}, {"code": "CLASS", "title": "뷰로베리타스(Bureau Veritas) VeriFuel, 2026년 2분기 글로벌 벙커유 품질 보고서 발간", "src": "Manifold Times", "date": "2026-07-28", "kSum": "프랑스 선급 뷰로베리타스(Bureau Veritas)의 연료검사 부문 VeriFuel이 2026년 2분기 벙커유 품질 보고서를 발간했다. VLSFO의 부적합률은 1.5%로 소폭 상승했으나 역사적 범위 내에 머물렀고, HSFO 부적합률은 2.4%로 2024년 초 이후 최고 수준을 기록했다. 포트클랑·싱가포르 등에서 알루미늄+실리콘(캣파인) 상승, 유럽 일부 항만에서 슬러지(침전물) 우려가 확인됐다.", "eSum": "VeriFuel, the fuel-testing arm of classification society Bureau Veritas, published its Q2 2026 global bunker fuel quality report. The VLSFO off-spec rate edged up to 1.5% but stayed within historical norms, while HSFO off-spec rose to 2.4%, the highest since early 2024. Elevated cat fines (Al+Si) were seen in Port Klang and Singapore, with sediment concerns in several European ports.", "kImp": "선급 계열 검사기관의 분기 품질 데이터는 선사·기술팀의 연료 관리·기기 보호에 실질적 참고자료가 되며, 블렌딩 다양화에 따른 연료 품질 리스크 모니터링의 중요성을 재확인시킨다.", "eImp": "Quarterly quality data from a class-society-linked inspection body offers practical guidance for owners and technical teams on fuel management and engine protection, reaffirming the importance of monitoring fuel-quality risk amid increasingly diverse blending.", "url": "https://www.manifoldtimes.com/news/bureau-veritas-verifuel-publishes-overview-of-q2-2026-global-bunker-fuel-quality/"}]}, {"code": "COMM", "type": "news", "kTitle": "Section 16. 상업·용선시장", "eTitle": "Section 16. Commercial & Chartering", "items": [{"code": "COMM", "title": "HMM, 컨테이너 선대 확충 위해 추가 발주 확대", "src": "The Loadstar", "date": "2026-07-27", "kSum": "HMM(에이치엠엠)이 허브앤스포크(hub-and-spoke) 네트워크를 뒷받침하기 위해 컨테이너선이 더 필요하다고 판단하고, 기존 신조 발주 계획을 상향해 추가 선박을 주문하기로 했다고 로드스타(The Loadstar)가 보도했다.", "eSum": "HMM has decided it needs more ships to support its hub-and-spoke liner model and is upsizing its newbuilding plan with extra containership orders, according to The Loadstar.", "kImp": "국적 원양선사의 선복 확대는 향후 동서항로 공급 증가와 운임 압박 요인이 될 수 있어 시장 수급에 직접적 영향을 준다.", "eImp": "Additional Korean-flag capacity adds to east-west supply growth and rate pressure, with direct implications for the supply-demand balance.", "url": "https://theloadstar.com/hmm-upsizes-plan-to-boost-box-shipping-fleet-with-extra-orders/"}, {"code": "COMM", "title": "CMA CGM, 프랑스 철도화물 1위 사업자 지분 인수 유력", "src": "The Loadstar", "date": "2026-07-27", "kSum": "CMA CGM(씨엠에이 씨지엠)이 프랑스 최대 철도화물 사업자 프레 SNCF(Fret SNCF) 지분 인수 유력 후보로 떠오르며 철도물류 분야로 사업 영역을 확장하려는 움직임을 보이고 있다고 로드스타가 전했다.", "eSum": "CMA CGM has emerged as the favourite to acquire a stake in Fret SNCF, France's top rail freight operator, expanding its footprint in rail logistics, The Loadstar reported.", "kImp": "대형 컨테이너 선사의 내륙·복합운송 수직계열화 확대는 물류시장 통합 흐름을 보여주며 화주 선택권과 경쟁 구도에 영향을 준다.", "eImp": "A liner giant deepening intermodal vertical integration signals continued logistics consolidation, affecting shipper choice and competition.", "url": "https://theloadstar.com/cma-cgm-favourite-to-acquire-stake-in-top-french-rail-freight-player/"}, {"code": "COMM", "title": "씨-인텔리전스: 6월 글로벌 정시성 62.6%로 하락", "src": "Container News", "date": "2026-07-28", "kSum": "씨-인텔리전스(Sea-Intelligence) 집계에서 2026년 6월 글로벌 정기선 정시운항률이 62.6%로 하락했다고 컨테이너뉴스(Container News)가 전했다. 홍해 우회와 항만 혼잡이 이어지며 스케줄 신뢰도가 약화됐다.", "eSum": "Global liner schedule reliability fell to 62.6% in June 2026 per Sea-Intelligence, as Red Sea diversions and port congestion continued to erode punctuality, Container News reported.", "kImp": "정시성 저하는 공급망 리드타임과 재고 비용을 키우고, 선사·화주 간 계약 협상과 스케줄 설계에 영향을 미친다.", "eImp": "Weaker reliability lengthens supply-chain lead times and inventory costs, shaping carrier-shipper contract talks and network design.", "url": "https://container-news.com/sea%e2%80%91intelligence-global-schedule-reliability-drops-to-62-6-in-june-2026/"}, {"code": "COMM", "title": "코스타마레, 2분기 이익 감소 속 13억 달러 금융 조달", "src": "Container News", "date": "2026-07-28", "kSum": "그리스 선사 코스타마레(Costamare)가 2분기 순이익이 감소한 가운데 13억 달러 규모의 금융 패키지를 확보했다고 컨테이너뉴스가 보도했다.", "eSum": "Costamare secured a US$1.3bn financing package even as its second-quarter profit declined, according to Container News.", "kImp": "선사의 대규모 자금 조달과 이익 둔화가 함께 나타난 점은 선대 투자 여력과 업황 사이클 변화를 보여주는 신호다.", "eImp": "The large financing amid softer earnings signals shifting fleet-investment capacity and cycle conditions.", "url": "https://container-news.com/costamare-secures-us1-3-billion-financing-package-as-q2-profit-declines/"}, {"code": "COMM", "title": "DHL 이커머스, 베니팍 인수해 발트 지역 확장", "src": "Container News", "date": "2026-07-28", "kSum": "DHL 이커머스(DHL eCommerce)가 물류기업 베니팍(Venipak)을 인수해 발트 3국 시장으로 사업을 확장한다고 컨테이너뉴스가 전했다.", "eSum": "DHL eCommerce is acquiring Venipak to expand across the Baltic markets, Container News reported.", "kImp": "대형 물류사의 지역 인수는 라스트마일·이커머스 물류 통합 흐름을 보여주며 유럽 물류 경쟁에 영향을 준다.", "eImp": "The acquisition reflects last-mile and e-commerce logistics consolidation, affecting European logistics competition.", "url": "https://container-news.com/dhl-ecommerce-to-acquire-venipak-and-expand-across-the-baltics/"}, {"code": "COMM", "title": "MSC, 유럽 근해항로 긴급유류할증료 조정", "src": "Container News", "date": "2026-07-28", "kSum": "MSC(엠에스씨)가 유럽 근해(short-sea) 항로에 적용하는 긴급유류할증료(EFS)를 갱신했다고 컨테이너뉴스가 보도했다. 벙커 가격과 운항비 변동을 반영한 조치다.", "eSum": "MSC has updated its Emergency Fuel Surcharge for European short-sea trades, reflecting bunker and operating-cost movements, per Container News.", "kImp": "할증료 조정은 화주의 실질 운임 부담과 근해 물류비에 직접 반영되는 비용 신호다.", "eImp": "Surcharge changes feed directly into shippers' effective freight costs and short-sea logistics expenses.", "url": "https://container-news.com/msc-updates-emergency-fuel-surcharge-for-european-short-sea-trades/"}, {"code": "COMM", "title": "그단스크항, 2026년 상반기 화물·컨테이너 물동량 사상 최대", "src": "Container News", "date": "2026-07-28", "kSum": "폴란드 그단스크항(Port of Gdańsk)이 2026년 상반기 총화물과 컨테이너 물동량에서 사상 최대 실적을 기록했다고 컨테이너뉴스가 전했다.", "eSum": "The Port of Gdańsk posted record cargo and container throughput in the first half of 2026, Container News reported.", "kImp": "발트해 관문항의 물동량 성장은 유럽 공급망의 대체 경로 부상과 역내 무역 확대를 시사한다.", "eImp": "Growth at this Baltic gateway points to rising alternative routings and expanding regional trade in Europe.", "url": "https://container-news.com/port-of-gdansk-reports-record-cargo-and-container-growth-in-first-half-of-2026/"}, {"code": "COMM", "title": "GT 라인스, 코르파칸 경유 동아프리카-걸프 신규 서비스 개설", "src": "Container News", "date": "2026-07-27", "kSum": "GT 라인스(GT Lines)가 UAE 코르파칸(Khorfakkan)을 경유하는 동아프리카-걸프 신규 컨테이너 서비스를 개설했다고 컨테이너뉴스가 보도했다.", "eSum": "GT Lines has launched a new East Africa-Gulf container service via Khorfakkan (UAE), according to Container News.", "kImp": "호르무즈 밖 코르파칸 허브를 활용한 신규 서비스는 걸프 물류의 대체 경로 수요와 역내 연결성 확대를 보여준다.", "eImp": "A new service via the Khorfakkan hub outside Hormuz reflects demand for alternative Gulf routings and expanding regional connectivity.", "url": "https://container-news.com/gt-lines-launches-east-africa-gulf-shipping-service-via-khorfakkan/"}, {"code": "COMM", "title": "코네크레인즈, 2026년 상반기 수주 큰 폭 증가", "src": "Container News", "date": "2026-07-27", "kSum": "항만 하역장비 제조사 코네크레인즈(Konecranes)가 2026년 상반기 강한 수주 증가를 보고했다고 컨테이너뉴스가 전했다.", "eSum": "Port equipment maker Konecranes reported strong order growth in the first half of 2026, Container News reported.", "kImp": "하역장비 수주 증가는 항만 투자와 터미널 생산성 확충 수요가 견조함을 보여주는 지표다.", "eImp": "Rising equipment orders indicate resilient port investment and demand for terminal productivity upgrades.", "url": "https://container-news.com/konecranes-reports-strong-order-growth-in-first-half-of-2026/"}]}, {"code": "GEO", "type": "news", "kTitle": "Section 17. 지정학", "eTitle": "Section 17. Geopolitics", "items": [{"code": "GEO", "title": "쿠에네+나겔, 걸프 육상 우회로 지속가능성에 회의적", "src": "The Loadstar", "date": "2026-07-27", "kSum": "쿠에네+나겔(Kuehne+Nagel) CEO가 호르무즈 해협(Strait of Hormuz) 통항 차질에 대응해 만든 걸프 육상 랜드브리지(landbridge)가 장기적 해법이 되기 어렵다며 경쟁사들보다 신중한 입장을 밝혔다고 로드스타(The Loadstar)가 보도했다.", "eSum": "Kuehne+Nagel's CEO said the Gulf landbridge developed in response to Strait of Hormuz disruption is not a sustainable long-term solution, taking a more cautious stance than peers, per The Loadstar.", "kImp": "호르무즈 리스크에 대한 대체 경로의 한계 지적은 걸프 물류의 구조적 취약성과 운임·리드타임 불확실성을 부각한다.", "eImp": "Doubts over the workaround highlight structural vulnerability of Gulf logistics and ongoing uncertainty in rates and lead times.", "url": "https://theloadstar.com/gulf-landbridge-not-a-sustainable-solution-says-kn-ceo/"}, {"code": "GEO", "title": "지정학 긴장에 선사들, 핵심 항로 집중·지역 서비스 축소", "src": "The Loadstar", "date": "2026-07-27", "kSum": "2분기 정기선 정시성은 소폭 개선됐지만 지정학적 긴장으로 선사들이 핵심 동서항로에 집중하고 지역 네트워크를 축소하면서 서비스가 갈수록 분절화되고 있다고 씨-인텔리전스(Sea-Intelligence) 분석을 인용해 로드스타가 전했다.", "eSum": "Though Q2 schedule reliability improved slightly, geopolitical tensions are pushing carriers to prioritise core east-west trades at the expense of regional networks, leaving services increasingly fragmented, The Loadstar reported citing Sea-Intelligence.", "kImp": "지정학 리스크가 항로 재편으로 이어지며 지역 시장의 연결성 약화와 물류비 격차 확대를 초래한다.", "eImp": "Geopolitical risk is reshaping route networks, weakening regional connectivity and widening logistics-cost gaps.", "url": "https://theloadstar.com/carriers-aim-for-schedule-reliability-on-core-trades-at-the-expense-of-regional-services/"}, {"code": "GEO", "title": "미국 신규 관세, 수입 급증 뒤 발효", "src": "Container News", "date": "2026-07-27", "kSum": "미국의 새 관세가 수입 물량 급증(사전 밀어내기) 이후 발효됐다고 컨테이너뉴스(Container News)가 보도했다. 화주들이 관세 시행 전 물량을 앞당기면서 나타난 흐름이다.", "eSum": "New US tariffs took effect following a surge in imports as shippers front-loaded cargo ahead of implementation, Container News reported.", "kImp": "관세 시행은 물동량 사이클(선반영 후 둔화)과 태평양항로 수요·운임에 직접적 영향을 미친다.", "eImp": "The tariffs drive front-load-then-slump volume cycles, directly affecting transpacific demand and rates.", "url": "https://container-news.com/new-us-tariffs-take-effect-after-import-surge/"}, {"code": "GEO", "title": "RCL, 보안 위험에 중국-홍해 항차 취소", "src": "Container News", "date": "2026-07-27", "kSum": "리저널 컨테이너 라인스 RCL(Regional Container Lines)이 보안 위험을 이유로 중국-홍해 항차를 취소했다고 컨테이너뉴스가 전했다. 홍해(Red Sea) 정세 불안이 서비스 결항으로 이어지고 있다.", "eSum": "Regional Container Lines (RCL) cancelled a China-Red Sea sailing over security risks, Container News reported, as Red Sea instability continues to trigger service suspensions.", "kImp": "홍해 리스크로 인한 결항은 아시아-유럽·중동 공급망 차질과 우회 비용 증가를 지속시킨다.", "eImp": "Red Sea-driven cancellations perpetuate Asia-Europe/Middle East supply disruption and higher diversion costs.", "url": "https://container-news.com/rcl-cancels-china-red-sea-sailing-over-security-risks/"}, {"code": "GEO", "title": "머스크, 케냐 신규 사전화물신고 요건 고객 안내", "src": "Container News", "date": "2026-07-28", "kSum": "머스크(Maersk)가 케냐의 새로운 사전화물신고(Advance Cargo Declaration) 요건 시행을 고객에게 안내했다고 컨테이너뉴스가 보도했다.", "eSum": "Maersk has advised customers of Kenya's new Advance Cargo Declaration requirement, Container News reported.", "kImp": "수입국의 사전신고 강화는 통관 절차와 서류 리스크를 키워 동아프리카 물류의 규제 부담을 높인다.", "eImp": "Tighter advance-declaration rules add customs and documentation risk, raising the regulatory burden for East Africa logistics.", "url": "https://container-news.com/maersk-advises-customers-of-kenyas-new-advance-cargo-declaration-requirement/"}, {"code": "GEO", "title": "홍해 교착 지속…물류시장 재편 논의", "src": "The Loadstar", "date": "2026-07-27", "kSum": "로드스타 프리미엄 분석 오션엑스(OceanX)는 홍해(Red Sea) 정세의 교착 상태가 이어지는 가운데 대형 물류사 간 경쟁과 중개시장 변화 등 시장 재편 이슈를 짚었다.", "eSum": "The Loadstar's premium OceanX briefing examined the continuing Red Sea stalemate alongside shifting competition among major forwarders and broker-market upheaval.", "kImp": "홍해 장기 교착은 우회 항로 고착과 운임 구조 변화를 이어가며 물류 경쟁 지형에 영향을 준다.", "eImp": "A prolonged Red Sea stalemate entrenches diversions and altered rate structures, reshaping the logistics competitive landscape.", "url": "https://theloadstar.com/oceanx-dsv-vs-kn-red-sea-stalemate-and-the-broker-bombshell/"}, {"code": "GEO", "title": "업계 여론: 홍해, 여전히 예측 불가", "src": "Container News", "date": "2026-07-27", "kSum": "컨테이너뉴스의 독자 의견(Readers Speak) 코너에서 업계 관계자들은 홍해(Red Sea) 정세가 여전히 예측 불가능하며 안정적 통항 재개를 확신하기 어렵다는 시각을 나타냈다.", "eSum": "In Container News' Readers Speak feature, industry voices said the Red Sea situation remains unpredictable, with little confidence in a stable return to transit.", "kImp": "시장의 불확실성 인식이 지속되면서 선사들은 홍해 복귀를 미루고 희망봉 우회 체제를 유지할 가능성이 크다.", "eImp": "Persistent uncertainty means carriers are likely to delay a Red Sea return and maintain Cape of Good Hope routing.", "url": "https://container-news.com/readers-speak-red-sea-remains-unpredictable-for-shipping/"}, {"code": "GEO", "title": "그레타 시핑·하파그로이드, 인도-걸프 서비스 재개", "src": "Container News", "date": "2026-07-27", "kSum": "그레타 시핑(Greta Shipping)과 하파그로이드(Hapag-Lloyd)가 인도-걸프(India-Gulf) 서비스를 재개한다고 컨테이너뉴스가 전했다.", "eSum": "Greta Shipping and Hapag-Lloyd are reinstating their India-Gulf service, Container News reported.", "kImp": "걸프 항로 서비스 재개는 역내 정세와 수요가 일부 안정되고 있음을 시사하며 중동 물류 연결성 회복을 보여준다.", "eImp": "Reinstating a Gulf service suggests some stabilisation in regional conditions and demand, signalling recovering Middle East connectivity.", "url": "https://container-news.com/greta-shipping-and-hapag-lloyd-reinstate-india-gulf-service/"}]}, {"code": "TW", "type": "news", "kTitle": "Section 18. TradeWinds 선박관리", "eTitle": "Section 18. TradeWinds Ship Management", "items": [{"code": "TW", "title": "Europe's $150m shadow fleet headache: Seized ships, stalled cases and no clear endgame", "src": "TradeWinds", "date": "2026-07-28", "kSum": "유럽이 나포한 그림자 선단(shadow fleet) 유조선들을 둘러싼 약 1억5천만 달러 규모의 골칫거리를 다룬 기사다(유료·헤드라인+요약 기준). 압류된 선박, 정체된 소송, 뚜렷하지 않은 결말이 핵심으로 언급됐다.", "eSum": "TradeWinds (paywalled; headline/snippet only) reports on Europe's roughly $150m shadow-fleet headache — seized ships, stalled legal cases and no clear endgame.", "kImp": "제재 회피 노후 선단의 나포·억류가 선박관리·보험·법률 리스크로 확대되며 관리사와 관계 당국의 부담이 가중된다.", "eImp": "Seizures and detentions of sanctions-evading ageing tonnage escalate management, insurance and legal risk, adding to the burden on managers and authorities.", "url": "https://www.tradewindsnews.com/ship-management/europe-s-150m-shadow-fleet-headache-seized-ships-stalled-cases-and-no-clear-endgame/2-1-2019362"}, {"code": "TW", "title": "Greek owner doubles money on VLCC asset play to Sinokor and MSC", "src": "TradeWinds", "date": "2026-07-28", "kSum": "한 그리스 선주가 VLCC 자산 매매를 통해 시노코(Sinokor)와 MSC에 매각하며 투자금을 두 배로 회수했다는 내용이다(유료·헤드라인 기준).", "eSum": "TradeWinds (paywalled; headline only) reports a Greek owner doubled its money on a VLCC asset play, selling to Sinokor and MSC.", "kImp": "강세장에서 중고 VLCC 자산 플레이가 큰 차익을 실현하며 선주들의 자산 순환이 가속된다.", "eImp": "A strong market lets secondhand VLCC asset plays deliver large gains, accelerating owners' asset rotation.", "url": "https://www.tradewindsnews.com/tankers/greek-owner-doubles-money-on-vlcc-asset-play-to-sinokor-and-msc/2-1-2021537"}, {"code": "TW", "title": "Turkish tanker player Ditas orders first suezmax newbuildings in a decade", "src": "TradeWinds", "date": "2026-07-28", "kSum": "터키 탱커사 디타스(Ditas)가 10년 만에 처음으로 수에즈막스(suezmax) 신조를 발주했다는 내용이다(유료·헤드라인 기준).", "eSum": "TradeWinds (paywalled; headline only) reports Turkish tanker player Ditas has ordered its first suezmax newbuildings in a decade.", "kImp": "중동 지정학 불안 속에서도 탱커 선복 확장이 이어지며 터키 선주의 신조 투자가 재개된다.", "eImp": "Even amid Middle East geopolitical risk, tanker fleet expansion continues as Turkish owners resume newbuilding investment.", "url": "https://www.tradewindsnews.com/tankers/turkish-tanker-player-ditas-orders-first-suezmax-newbuildings-in-a-decade/2-1-2021465"}, {"code": "TW", "title": "Greek shipowner JME returns to China for ultramax bulk carriers", "src": "TradeWinds", "date": "2026-07-28", "kSum": "그리스 선주 JME가 울트라막스(ultramax) 벌크선 확보를 위해 다시 중국 조선소를 찾았다는 내용이다(유료·헤드라인 기준).", "eSum": "TradeWinds (paywalled; headline only) reports Greek shipowner JME has returned to China for ultramax bulk carriers.", "kImp": "벌크 선주의 중국 신조 발주가 지속되며 건화물 선대 확충 흐름이 이어진다.", "eImp": "Continued Chinese newbuilding orders by bulker owners sustain the dry-cargo fleet-expansion trend.", "url": "https://www.tradewindsnews.com/bulkers/greek-shipowner-jme-returns-to-china-for-ultramax-bulk-carriers/2-1-2021482"}, {"code": "TW", "title": "Berlian Laju stocks up on LPG carriers as it pivots towards gas", "src": "TradeWinds", "date": "2026-07-28", "kSum": "인도네시아 선사 벌리안 라주(Berlian Laju)가 가스 부문으로 사업을 전환하며 LPG선을 대거 확보하고 있다는 내용이다(유료·헤드라인 기준).", "eSum": "TradeWinds (paywalled; headline only) reports Berlian Laju is stocking up on LPG carriers as it pivots towards gas.", "kImp": "가스 시장 성장에 대응한 선대 재편으로 LPG 선복 수요가 확대된다.", "eImp": "Fleet reshaping toward a growing gas market is broadening demand for LPG tonnage.", "url": "https://www.tradewindsnews.com/gas/berlian-laju-stocks-up-on-lpg-carriers-as-it-pivots-towards-gas/2-1-2021475"}, {"code": "TW", "title": "Turkish shipowner Aruna set to double its fleet with Chinese newbuilding series", "src": "TradeWinds", "date": "2026-07-28", "kSum": "터키 선주 아루나(Aruna)가 중국 신조 시리즈를 통해 선대를 두 배로 확대할 계획이라는 내용이다(유료·헤드라인 기준).", "eSum": "TradeWinds (paywalled; headline only) reports Turkish shipowner Aruna is set to double its fleet with a Chinese newbuilding series.", "kImp": "터키 선주들의 공격적 선대 확장이 이어지며 중국 조선소의 수주가 지속된다.", "eImp": "Aggressive fleet expansion by Turkish owners continues to feed Chinese shipyards' orderbooks.", "url": "https://www.tradewindsnews.com/bulkers/turkish-shipowner-aruna-set-to-double-its-fleet-with-chinese-newbuilding-series/2-1-2021345"}, {"code": "TW", "title": "Skuld involved in second plastic pellet clear-up off English coast in 18 months", "src": "TradeWinds", "date": "2026-07-28", "kSum": "P&I 클럽 스쿨드(Skuld)가 18개월 만에 두 번째로 영국 연안의 플라스틱 펠릿(nurdle) 유출 정화 작업에 관여하고 있다는 내용이다(유료·헤드라인 기준).", "eSum": "TradeWinds (paywalled; headline only) reports Skuld is involved in a second plastic pellet clear-up off the English coast in 18 months.", "kImp": "반복되는 펠릿 유출 대응으로 P&I 및 선박관리의 환경 배상·정화 부담이 부각된다.", "eImp": "Repeated pellet spills highlight the environmental liability and clean-up burden falling on P&I and ship management.", "url": "https://www.tradewindsnews.com/tankers/skuld-involved-in-second-plastic-pellet-clear-up-off-english-coast-in-18-months/2-1-2021549"}, {"code": "TW", "title": "James Fisher newbuilding steals the show at Tower Bridge", "src": "TradeWinds", "date": "2026-07-28", "kSum": "제임스 피셔(James Fisher)의 신조선이 런던 타워브리지(Tower Bridge)에서 주목을 받았다는 인터뷰 기사다(유료·헤드라인 기준).", "eSum": "TradeWinds (paywalled; headline only) carries an interview noting a James Fisher newbuilding stole the show at Tower Bridge.", "kImp": "선주의 신조선 홍보·브랜딩 사례로, 영국 선주의 선대 갱신 움직임을 보여준다.", "eImp": "An owner newbuilding showcase that illustrates UK owner fleet-renewal activity.", "url": "https://www.tradewindsnews.com/tankers/james-fisher-newbuilding-steals-the-show-at-tower-bridge/2-1-2021109"}, {"code": "TW", "title": "Up not down: Genco Shipping rebuts Diana claims on falling bulker values", "src": "TradeWinds", "date": "2026-07-28", "kSum": "젠코 시핑(Genco Shipping)이 벌크선 가치가 하락하고 있다는 디아나 시핑(Diana Shipping)의 주장을 반박하며 오히려 상승세라고 밝혔다는 내용이다(유료·헤드라인 기준).", "eSum": "TradeWinds (paywalled; headline only) reports Genco Shipping rebutted Diana Shipping's claim of falling bulker values, saying they are up not down.", "kImp": "디아나-젠코 인수 공방이 이어지는 가운데 벌크선 자산가치를 둘러싼 논쟁이 M&A 향방에 영향을 미친다.", "eImp": "Amid the ongoing Diana-Genco takeover tussle, the dispute over bulker asset values bears on the M&A outcome.", "url": "https://www.tradewindsnews.com/finance/up-not-down-genco-shipping-rebuts-diana-claims-of-falling-bulker-values/2-1-2021413"}]}, {"code": "HOT", "type": "news", "kTitle": "Section 19. 핫이슈: 호르무즈 해협", "eTitle": "Section 19. Hot Topic: Strait of Hormuz", "items": [{"code": "HOT", "title": "Trump Says US and Tehran Having 'Good Talks' as Drones Hit Iran's Neighbors", "src": "gCaptain", "date": "2026-07-27", "kSum": "트럼프(Trump) 대통령이 이란과 \"좋은 대화(good talks)\"를 하고 있으며 합의 가능성이 있다고 밝혔으나, 협상 실패 시 공습을 재개하겠다고 경고했다. 미국은 13일간 이어진 공습을 토요일 갑자기 중단했다. 이란은 여전히 호르무즈 해협(Strait of Hormuz)을 통제한다며, 국영매체는 허가 없이 통항하려던 6척을 월요일 아침 회항시켰다고 전했다. 같은 날 사우디·요르단·이라크에 드론 공격이 발생했고, 지난주 100달러를 넘었던 브렌트유는 8.2% 급락해 89달러를 밑돌았다.", "eSum": "President Trump said the US was having 'good talks' with Iran and a deal was possible, but warned strikes would resume if talks failed. Washington abruptly halted its 13-night bombing campaign on Saturday. Iran said it still controls the Strait of Hormuz, with state media reporting it turned back six ships that tried to transit without permission on Monday. Saudi Arabia, Jordan and Iraq reported drone attacks the same day, and Brent crude fell 8.2% to below $89.", "kImp": "해협 통제권을 둘러싼 미·이란 대치가 외교와 무력 사이를 오가며, 이란의 통항 허가·통행료 부과 방침이 상선 운항 리스크의 핵심 변수로 남아 있다.", "eImp": "The US-Iran standoff over control of the strait swings between diplomacy and force, keeping Iran's transit-permission and toll agenda the key variable for commercial shipping risk.", "url": "https://gcaptain.com/trump-says-us-and-tehran-having-good-talks-as-drones-hit-irans-neighbors/"}, {"code": "HOT", "title": "Iran Says It Still Controls Strait, Not Seeking Talks, After Trump Halts Bombing", "src": "gCaptain", "date": "2026-07-27", "kSum": "이란은 트럼프(Trump)가 2주간의 공습을 중단한 뒤에도 호르무즈 해협을 계속 통제하고 있으며 미국과의 협상 재개를 원하지 않는다고 밝혔다. 국영매체는 허가 없이 통항하려던 6척을 회항시켰고 그중 1척은 \"사고(accident)\"가 있었다고 전했다. 이란은 자국 연안에 가까운 지정 항로만 허용하고 통행료를 부과할 방침이며, 반대편 연안을 관할하는 오만(Oman)과 해협 관리 합의를 추진 중이다. 미 참모진은 표적 소진과 방공 무기 부족을 이유로 공습 중단을 조언한 것으로 전해졌다.", "eSum": "Iran said it still controls the Strait of Hormuz and is not seeking to resume talks after Trump halted a two-week bombing campaign that his commanders said had run out of targets. State media said six 'offending ships' were turned back Monday, one suffering an 'accident.' Iran insists vessels use only its designated channel near its coast, where it plans transit fees, and is pursuing a strait-management deal with Oman.", "kImp": "이란이 자국 항로만 허용하고 통행료를 부과하려는 방침을 고수하고 오만과의 합의를 추진하면서 해협 통제 공식화를 시도, 통항 선박의 불확실성이 장기화될 전망이다.", "eImp": "Iran's insistence on its own channel plus tolls, and its push for an Oman deal to formalize control, points to prolonged uncertainty for transiting vessels.", "url": "https://gcaptain.com/iran-says-it-still-controls-strait-not-seeking-talks-after-trump-halts-bombing/"}, {"code": "HOT", "title": "'Goodbye, Engine Room': Trump Floods Truth Social With AI Images of Captured and Exploding Iranian Tankers", "src": "gCaptain", "date": "2026-07-27", "kSum": "트럼프(Trump) 대통령이 트루스소셜(Truth Social)에 미군이 이란 유조선을 나포·폭파하는 AI 생성 이미지를 다수 게시했다. \"이제 우리 유조선(It's Our Oil Tanker Now)\", \"Goodbye, Engine Room\" 등의 문구가 담겼다. 3일 연속 직접적 무력충돌은 없었으나 긴장은 여전하며, 예멘 후티(Houthi)의 홍해 상선 공격 재개로 홍해와 호르무즈 해협에서 동시 위협 우려가 커진 가운데 해상 안보가 양국 대치의 중심임을 부각했다.", "eSum": "Trump posted a series of AI-generated images on Truth Social showing US forces seizing and blowing up Iranian oil tankers, with captions such as 'It's Our Oil Tanker Now' and 'Goodbye, Engine Room.' The posts came after three nights without direct strikes but amid persistent tension, and as renewed Houthi attacks in the Red Sea raised fears of simultaneous threats in both the Red Sea and Strait of Hormuz.", "kImp": "정상급의 위협적 메시지가 이어지며 이란 유조선·상선에 대한 물리적 나포·타격 리스크가 지속돼 선주·용선주 심리가 위축된다.", "eImp": "Continued threatening messaging at the presidential level keeps the risk of physical seizure or strikes on Iranian tankers alive, weighing on owner and charterer sentiment.", "url": "https://gcaptain.com/goodbye-engine-room-trump-floods-truth-social-with-ai-images-of-captured-and-exploding-iranian-tankers/"}, {"code": "HOT", "title": "India Flags Attack on LPG Tanker in Iran Waters, Says Crew Safe", "src": "gCaptain", "date": "2026-07-27", "kSum": "인도인 28명이 승선한 LPG선 디샤(DISHA)호가 금요일 이란 영해에서 공격을 받았으나 선원은 안전하다고 인도 테헤란 대사관이 확인했다. 별도로 흑해에서 상선 MV 오모르피(OMORFI)호가 피격돼 인도 선원 1명이 사망하고 2명은 안전한 것으로 전해졌다. 인도 해운총국은 예멘·바브엘만데브(Bab-el-Mandeb)·남홍해 통항 시 \"최고 수준의 주의\"를 당부했다.", "eSum": "India's embassy in Tehran said an LPG tanker, DISHA, with 28 Indian crew was attacked in Iranian territorial waters on Friday, but the crew are safe. Separately, the vessel MV OMORFI was attacked in the Black Sea, killing one Indian seafarer. India's shipping directorate urged the 'highest degree of caution' when transiting near Yemen, the Bab-el-Mandeb strait and the southern Red Sea.", "kImp": "호르무즈·이란 영해에서 상선 피격이 이어지며 선원 안전 우려와 인도 등 공급국의 통항 기피가 확대되고 있다.", "eImp": "Continued strikes on merchant ships in and around Hormuz and Iranian waters heighten seafarer-safety concerns and reinforce transit avoidance by supplier states like India.", "url": "https://gcaptain.com/india-flags-attack-on-lpg-tanker-in-iran-waters-says-crew-safe/"}, {"code": "HOT", "title": "Reality of the Crude Trade Will Come to a Head Around Midterms", "src": "gCaptain", "date": "2026-07-27", "kSum": "며칠간 공격이 없어 유가가 90달러를 밑돌지만 이는 중동의 실제 공급 현실을 반영하지 못한다는 분석이다. 호르무즈 해협의 사실상 폐쇄, 홍해 차질, 러시아 정제품 수출 차질이 겹친 \"삼중 악재\"로 공급 부족이 심화되고 있다. 아프리카 우회와 수에즈 환적으로 아시아행 원유가 약 60일 지연되며, 미 전략비축유(SPR)는 1983년 이후 최저인 3억1145만 배럴로 감소했다. 분석가들은 향후 3개월 내 미 중간선거에 영향을 미칠 수 있다고 우려한다.", "eSum": "Oil below $90 does not reflect the Middle East supply reality, the piece argues. A 'losing trifecta' of the near-closure of the Strait of Hormuz, Red Sea disruption and lost Russian refined-product exports is deepening a shortage. Diversions around Africa and Suez transshipment add ~60 days to Asia-bound crude, while the US SPR has fallen to 311.45m barrels, its lowest since 1983. Analysts warn the disruption could affect the US midterms within three months.", "kImp": "호르무즈 봉쇄 장기화가 원유 재고 소진과 가격 급등, 정치 리스크로 전이되며, 탱커 운임 상승과 항로 재편을 가속한다.", "eImp": "A prolonged Hormuz shutdown risks draining inventories and spiking prices, feeding into political risk while accelerating higher tanker rates and route reshaping.", "url": "https://gcaptain.com/reality-of-the-crude-trade-will-come-to-a-head-around-midterms/"}, {"code": "HOT", "title": "Oil Keeps Flowing From Red Sea As Hormuz Bypass Stays Open", "src": "gCaptain", "date": "2026-07-25", "kSum": "이란이 호르무즈 해협을 통한 원유 흐름을 차단하려는 가운데, 사우디는 홍해 얀부(Yanbu)항을 우회로로 활용해 수출을 지속하고 있다. 서방 선주들은 바브엘만데브(Bab el-Mandeb) 회피 또는 트랜스폰더를 끈 채 통항하고, 중국 등 이란 우호국 선박은 계속 통과 중이다. 덴마크 톰(Torm)의 제품선 톰 이노베이션(Torm Innovation) 등 일부 유조선은 수에즈 북향 우회로 선회했고, 최근 며칠간 초대형 유조선 3척이 AIS를 끄고 걸프를 빠져나갔다.", "eSum": "Despite Iran's push to stop crude flowing through the Strait of Hormuz, Saudi Arabia keeps exporting via its Red Sea port of Yanbu. Western owners are avoiding Bab el-Mandeb or transiting with transponders off, while Chinese and other Iran-affiliated vessels keep crossing. Some tankers, such as Denmark's Torm Innovation, u-turned toward the Suez route, and three VLCCs recently exited the Gulf 'dark' in recent days.", "kImp": "호르무즈 봉쇄로 홍해 얀부가 핵심 우회 허브로 부상했으나 후티 위협으로 이마저 불안정해지면서, AIS 소등·희망봉 우회 등 운항 관행 변화가 확산된다.", "eImp": "With Hormuz effectively blocked, Yanbu has become the key workaround hub, but Houthi threats destabilize even that, spreading practices like AIS-dark sailing and Cape of Good Hope diversions.", "url": "https://gcaptain.com/oil-keeps-flowing-from-red-sea-as-hormuz-bypass-stays-open/"}, {"code": "HOT", "title": "Red Sea Shipping Slows After Houthi Attack On Saudi Arabia", "src": "gCaptain", "date": "2026-07-26", "kSum": "예멘 후티(Houthi)가 홍해 연안 사우디 석유시설을 공격한 뒤 일요일 바브엘만데브(Bab el-Mandeb) 통항량이 감소했다. 호르무즈 해협 위기와 맞물려 홍해·걸프 양대 해상 요충지에서 상선 통항이 위축되고 있다.", "eSum": "Ship traffic through Bab el-Mandeb fell on Sunday after Yemen's Houthis attacked Saudi oil installations along the Red Sea coast. Combined with the Strait of Hormuz crisis, merchant transits are contracting across both major maritime chokepoints.", "kImp": "이란-호르무즈 위기가 홍해로 확산되며 글로벌 에너지 물류의 이중 병목 리스크가 현실화하고 있다.", "eImp": "The Iran-Hormuz crisis spilling into the Red Sea makes the twin-chokepoint bottleneck risk to global energy logistics a growing reality.", "url": "https://gcaptain.com/red-sea-shipping-slows-after-houthi-attack-on-saudi-arabia/"}, {"code": "HOT", "title": "Oman proposes new Strait of Hormuz plan to Iran with voluntary fee for shipping", "src": "TradeWinds", "date": "2026-07-28", "kSum": "트레이드윈즈(TradeWinds) 보도(유료·헤드라인 기준)에 따르면, 오만(Oman)이 이란에 호르무즈 해협 관련 새로운 방안을 제안했으며, 여기에는 통항 선박에 자발적 수수료(voluntary fee)를 부과하는 구상이 포함된 것으로 전해졌다. (유료 기사로 상세 내용은 미확인)", "eSum": "Per TradeWinds (paywalled; headline-based), Oman has proposed a new Strait of Hormuz plan to Iran that reportedly includes a voluntary fee for shipping passing through the waterway. (Full details behind paywall, unverified.)", "kImp": "오만이 중재자로 나서 이란의 통항료 부과를 제도화하려는 움직임으로, 해협 통제·과금 논의가 실무 단계로 진입할 가능성을 시사한다.", "eImp": "Oman stepping in as mediator to institutionalize an Iranian transit fee suggests the strait's control-and-charging debate may be moving toward a practical framework.", "url": "https://www.tradewindsnews.com/gas/oman-proposes-new-strait-of-hormuz-plan-to-iran-with-voluntary-fee-for-shipping/2-1-2021604"}]}, {"code": "SYS", "type": "news", "kTitle": "Section 20. 시스템·앱", "eTitle": "Section 20. System & App", "items": [{"code": "SYS", "title": "CHS, 오픈터그(OpenTug) 투자로 미국 바지선 물류에 디지털 플랫폼 도입", "src": "Splash247", "date": "2026-07-25", "kSum": "미국 농업협동조합 CHS가 해양물류 기술기업 오픈터그(OpenTug)에 투자하고 자사 공급망 전반에 디지털 바지선 관리 플랫폼을 도입한다. 투자는 CHS와 농업협동조합 그로우마크(GROWMARK) 합작사 코퍼러티브벤처스(Cooperative Ventures)를 통해 이뤄졌다. 오픈터그의 바지OS(BargeOS) 플랫폼은 상업 계획, 항해 관리, 화물 추적, 송장 정산, 리포팅을 통합하며 실시간 바지선 위치 추적과 운항 메시지 자동 처리로 유휴 일수·체선료 절감과 도착시간 예측 개선을 지원한다.", "eSum": "US agribusiness cooperative CHS is deploying a digital barge-management platform across its supply chain after investing in marine logistics technology firm OpenTug via Cooperative Ventures, its joint venture with GROWMARK. OpenTug's BargeOS platform combines commercial planning, voyage management, cargo tracking, invoice reconciliation and reporting, with real-time barge positioning and automated traffic-report processing to cut idle days and demurrage while improving ETAs.", "kImp": "화주(대형 협동조합)가 직접 해운물류 소프트웨어에 전략투자한 사례로, 내륙수운·터미널 네트워크의 디지털 운항관리 수요를 보여준다. 항해관리·화물추적·정산을 통합한 SaaS가 벌크·바지선 부문으로 확산되는 흐름을 반영한다.", "eImp": "A cargo owner making a strategic investment directly in maritime logistics software signals demand for digital voyage management across inland and terminal networks, reflecting the spread of integrated voyage-tracking-settlement SaaS into bulk and barge segments.", "url": "https://splash247.com/chs-backs-digital-platform-for-us-barge-logistics/"}, {"code": "SYS", "title": "라쿠텐마리타임(Rakuten Maritime), 스마트십허브(Smart Ship Hub) 플랫폼에 사이버보안 결합", "src": "Splash247", "date": "2026-07-27", "kSum": "선주·운항사 대상 사이버보안 기업 라쿠텐마리타임(Rakuten Maritime)이 스마트십허브(Smart Ship Hub)와 손잡고 선대 성능관리 기술에 선박 전주기 사이버보안을 결합한다. 스마트십허브의 디지털 플랫폼은 항해 계획, 기상 라우팅, 연료성능 분석, 기관 상태 모니터링, 실시간 선대 진단을 제공한다. 라쿠텐마리타임은 설계·건조·시운전·운항 단계까지 '설계기반 보안(cybersecurity-by-design)' 역량을 적용해, 운항 데이터와 사이버 리스크를 분리된 시스템이 아닌 연결된 선대 운영의 일부로 관리하도록 한다.", "eSum": "Rakuten Maritime, a cybersecurity provider for shipowners and operators, has partnered with Smart Ship Hub to combine fleet performance technology with cybersecurity across the vessel lifecycle. Smart Ship Hub's digital platform offers voyage planning, weather routing, fuel-performance analysis, machinery condition monitoring and real-time fleet diagnostics, while Rakuten adds cybersecurity-by-design from design and construction through operation, managing operational data and cyber risk as connected parts of fleet operations.", "kImp": "성능관리 SaaS와 해상 사이버보안을 통합하려는 시도로, 온보드 IT·OT 시스템이 늘며 사이버 리스크가 일상 선대관리의 일부로 편입되는 흐름을 보여준다. 선박 디지털 플랫폼의 보안 내재화가 신규 경쟁 축으로 부상하고 있음을 시사한다.", "eImp": "Merging performance-management SaaS with maritime cybersecurity shows cyber risk becoming part of routine fleet management as onboard IT/OT proliferates, signalling that built-in security is emerging as a new axis of competition for vessel digital platforms.", "url": "https://splash247.com/rakuten-maritime-adds-cyber-layer-to-smart-ship-hub-platform/"}, {"code": "SYS", "title": "민트라(Mintra), 훈련 플랫폼 트레이닝포털을 노르웨이 역량등록부 K-REG와 연동", "src": "Splash247", "date": "2026-07-28", "kSum": "해양·오프쇼어 교육 SaaS 기업 민트라(Mintra)가 자사 학습·역량관리 시스템 트레이닝포털(TrainingPortal)을 노르웨이 국가 디지털 역량등록부 K-REG와 연동했다. 교육 이수 시 결과가 K-REG에 자동 전송돼 고용주가 공식 역량 기록을 수기로 갱신할 필요가 없어진다. 선원·오프쇼어 인력이 선박·현장·계약사·관할을 오가며 자격 증빙 부담이 큰 상황에서, 수기 이전에 따른 지연·오류를 줄이고 자격의 정확성·최신성·감사 대응성을 높이는 것이 목표다. 해당 통합은 즉시 이용 가능하다.", "eSum": "Maritime and offshore training SaaS firm Mintra has launched an integration linking its TrainingPortal learning and competency management system with K-REG, Norway's national digital competence registry. Course results transfer automatically into K-REG on completion, removing manual updates by employers. Aimed at maritime, offshore and energy firms managing mobile workforces, it reduces delays and errors from manual transfers and keeps qualifications accurate, current and auditable. The integration is available immediately.", "kImp": "선원 역량관리 SaaS가 국가 자격등록부와 직접 연동된 사례로, 크루잉·교육 소프트웨어가 규제 준수·감사 대응 자동화로 진화하는 흐름을 보여준다. 이동성이 큰 해양 인력의 자격 검증을 디지털화해 배승 전 컴플라이언스 리스크를 낮추는 방향을 제시한다.", "eImp": "A crew-competence SaaS integrating directly with a national qualification registry shows crewing and training software evolving toward automated compliance and audit readiness, digitalising qualification checks for mobile maritime workforces and lowering pre-deployment compliance risk.", "url": "https://splash247.com/mintra-links-training-platform-to-norways-competence-registry/"}, {"code": "SYS", "title": "CJ대한통운-한국환경공단, AI 적정포장 검증체계 구축…솔루션 '팩체크(PackCheck)' 고도화", "src": "코리아쉬핑가제트(KSG)", "date": "2026-07-27", "kSum": "CJ대한통운이 한국환경공단과 인공지능(AI) 기반 스마트 적정포장 체계 구축·운영 업무협약(MOU)을 체결했다. CJ대한통운은 TES물류기술연구소가 개발한 AI 적정포장 판정 솔루션 '팩체크(PackCheck)'를 고도화하고, 환경공단은 분석결과 적합성 검토, 규제기준 정량화, 스마트 적정포장 인증제 도입, 현장 점검 등 기술지원을 맡는다. 팩체크는 상품 정보·규격·포장재를 분석해 포장공간비율 준수 여부를 판정하며 현재 전국 26개 물류센터에서 운영 중이다. 양 기관은 'AI 적정포장 검증 운영위원회'도 구성한다.", "eSum": "CJ Logistics signed an MOU with the Korea Environment Corporation to build and operate an AI-based smart packaging verification system. CJ Logistics will enhance PackCheck, an AI packaging-adequacy solution from its TES logistics tech institute, while the state agency provides technical support including result reviews, regulatory quantification, a smart packaging certification scheme and site inspections. PackCheck analyses product data, dimensions and materials to judge compliance with packaging-space ratios and runs at 26 CJ Logistics centres nationwide.", "kImp": "물류 소프트웨어가 민관 협력을 통해 규제 검증 표준으로 발전하는 국내 사례로, AI 판정 솔루션이 수작업 검사 업무를 디지털화·표준화하는 흐름을 보여준다. 과대포장 규제 준수 자동화 수요와 국산 물류테크의 제도권 편입 가능성을 부각한다.", "eImp": "A domestic case of logistics software evolving into a regulatory verification standard through public-private cooperation, showing AI adjudication digitalising and standardising manual inspection. It highlights demand for automated packaging-compliance and the potential institutionalisation of Korean logistics tech.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147705"}]}, {"code": "SMGR", "type": "news", "kTitle": "Section 21. 선박관리사", "eTitle": "Section 21. Ship Managers", "items": [{"code": "SMGR", "title": "World's largest shipmanager sees owners demanding more than technical management", "src": "Splash247", "date": "2026-07-22", "kSum": "세계 최대 선박관리사 앵글로-이스턴 유니반 그룹(Anglo-Eastern Univan Group)의 비외른 회고르(Bjorn Hojgaard) CEO는 사내 매거진 기고에서, 선박관리업이 기술관리와 비용통제를 넘어 지정학·규제·사이버·인력 리스크로부터 선주를 보호하는 역할로 확장되고 있다고 밝혔다. 그는 앵글로-이스턴이 선원 육성, 디지털 인프라, 탄소 서비스, 사이버보안, 보안 정보 분야에 투자하고 있다고 강조했다. AI는 반복 업무를 대체하되 안전에 직결된 판단은 숙련 인력에 맡긴다는 전략도 제시했다.", "eSum": "Bjorn Hojgaard, CEO of Anglo-Eastern Univan Group, the world's largest shipmanager, wrote in the company's in-house magazine that shipmanagement is expanding beyond technical operations and cost control toward protecting owners from geopolitical, regulatory, cyber and workforce risks. He stressed that Anglo-Eastern is investing across seafarer development, digital infrastructure, carbon services, cybersecurity and security intelligence. AI, he said, should replace repetition while leaving safety-critical decisions to experienced people.", "kImp": "선박관리가 가격 중심의 상품이 아니라 엔지니어링·선원술·판단력에 기반한 전문 서비스로 재정의되고 있음을 보여주며, 탈탄소·디지털 전환 속에서 관리사 간 부가가치 경쟁이 심화될 것임을 시사한다.", "eImp": "It signals that shipmanagement is being redefined as a professional craft built on engineering, seamanship and judgement rather than a price-based commodity, intensifying value-added competition among managers amid decarbonisation and digital transformation.", "url": "https://splash247.com/worlds-largest-shipmanager-sees-owners-demanding-more-than-technical-management/"}, {"code": "SMGR", "title": "Columbia Group's CEO sets out priorities for next phase of growth", "src": "Cyprus Shipping News", "date": "2026-07-22", "kSum": "컬럼비아 그룹(Columbia Group)의 안드레아스 하지페트루(Andreas Hadjipetrou) CEO가 책임 있는 성장, 협업 강화, 선원 지원, 장기적 고객 신뢰를 그룹 전략의 중심에 두겠다는 우선순위를 제시했다. 그는 그룹 내 기업·사무소·부서 간 협력과 정보 공유 강화, 선원의 근무여건·안전·복지·훈련 개선을 최우선 과제로 꼽았다. 핵심 선박관리 사업을 계속 성장시키면서 그룹의 부가 서비스도 확대하겠다고 밝혔다.", "eSum": "Andreas Hadjipetrou, CEO of Columbia Group, set out priorities placing responsible growth, stronger collaboration, seafarer support and long-term client trust at the centre of the group's strategy. He named strengthening cooperation and information sharing across the group's companies and offices, and improving seafarers' working conditions, safety, wellbeing and training, as immediate priorities. Columbia will keep growing its core shipmanagement activities while developing wider group services.", "kImp": "탈탄소·기술·규제 변화 속에서 신뢰·거버넌스·선원 복지를 앞세운 '측정 가능하고 수익성 있는' 성장 노선을 제시함으로써, 대형 선박관리사의 향후 방향성을 가늠할 수 있는 신호가 된다.", "eImp": "By emphasising trust, governance and crew welfare while pursuing 'measured, profitable' growth amid decarbonisation, technology and regulatory change, it offers a signal of how a large shipmanager intends to steer its next phase.", "url": "https://cyprusshippingnews.com/2026/07/22/columbia-groups-ceo-sets-out-priorities-for-next-phase-of-growth/"}]}]};